window.__PIONEER_REGISTER_TEST("TEST_HIST_SET_20", [
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. फ्रांस्वा बर्नियर एवं टैवर्नियर   B. गुरु हरगोबिंद (छठे गुरु)\nC. चौसा का युद्ध (1539 ई.)   D. बीजापुर (आदिलशाही, 1489)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["चौसा का युद्ध (1539 ई.)","फ्रांस्वा बर्नियर एवं टैवर्नियर","बीजापुर (आदिलशाही, 1489)","गुरु हरगोबिंद (छठे गुरु)"],"correct":1,"explanation":"बीजापुर (आदिलशाही, 1489) (1489 ई.), चौसा का युद्ध (1539 ई.) (1539 ई.), गुरु हरगोबिंद (छठे गुरु) (1606-1644 ई.), फ्रांस्वा बर्नियर एवं टैवर्नियर (1658 ई.)। अतः सबसे अंत में फ्रांस्वा बर्नियर एवं टैवर्नियर।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. अकबर की 'दीन-ए-इलाही' (तौहीद-ए-इलाही) एक कट्टर इस्लामी सैन्य संहिता थी जिसे राजा मानसिंह और भगवानदास ने तुरंत स्वीकार किया था।\n2. 1722 में अवध का सूबेदार बनकर सआदत खाँ ने राजस्व सुधार कर स्वतंत्र अवध की नींव डाली।\n3. मुर्शिद कुली खाँ ने राजधानी ढाका से मुर्शिदाबाद स्थानांतरित की व 'तकावी' कृषि ऋण दिए।\n4. बाबा फरीद (फरीदुद्दीन गंज-ए-शकर) के भक्तिपूर्ण श्लोक सिखों के पवित्र ग्रंथ 'गुरु ग्रंथ साहिब' में संकलित किए गए हैं।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":0,"explanation":"कथन 1 असत्य है। सुधार: दीन-ए-इलाही 'सुलह-ए-कुल' (सार्वभौमिक शांति) पर आधारित नैतिक आचार संहिता थी; मानसिंह ने इसे स्वीकार करने से साफ मना कर दिया, केवल बीरबल ने इसे अपनाया।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक युद्ध एवं परिणाम] निम्नलिखित युग्मों पर विचार कीजिए:\n1. खानवा का युद्ध (1527 ई.) : बाबर ने मेवाड़ के राणा सांगा को हराकर 'गाजी' उपाधि ली\n2. तराइन का प्रथम युद्ध (1191 ई.) : पृथ्वीराज चौहान तृतीय ने मुहम्मद गौरी को पराजित किया\n3. नर्मदा तट का युद्ध (पुलकेशिन II बनाम हर्ष) : राजा सुदास (भरत जन) ने दस राजाओं के संघ को पराजित किया\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (16 मार्च 1527 को खानवा के युद्ध में बाबर ने राणा सांगा के नेतृत्व वाले राजपूत संघ को परास्त किया।) युग्म 2 सही (1191 ई. में तराइन के प्रथम युद्ध में पृथ्वीराज चौहान ने मुहम्मद गौरी को पराजित किया।) युग्म 3 गलत (सही: नर्मदा तट का युद्ध (पुलकेशिन II बनाम हर्ष) — चालुक्य नरेश पुलकेशिन द्वितीय ने हर्षवर्धन को हराया)।"},
  {"q":"[UPSC Prelims पैटर्न — मुगलकालीन प्रमुख युद्ध] निम्नलिखित युग्मों पर विचार कीजिए:\n1. सामूगढ़ का युद्ध (1658 ई.) : औरंगजेब व मुराद बनाम दारा शिकोह\n2. हल्दीघाटी युद्ध (1576 ई.) : शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय\n3. चौसा का युद्ध (1539 ई.) : नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला'\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (मई 1658 में आगरा के निकट सामूगढ़ युद्ध में औरंगजेब की जीत से शाहजहाँ कैद व उत्तराधिकार तय हुआ।) युग्म 2 गलत (सही: हल्दीघाटी युद्ध (1576 ई.) — महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ))। युग्म 3 गलत (सही: चौसा का युद्ध (1539 ई.) — शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय)।"},
  {"q":"[UPSC Prelims पैटर्न — विदेशी यात्री एवं शासक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. फ्रांस्वा बर्नियर एवं टैवर्नियर : शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68)\n2. निकोलो कोंटी (इटली) : कृष्णदेवराय (विजयनगर, ~1520 ई.)\n3. डोमिंगो पायस (पुर्तगाल) : मुहम्मद बिन तुगलक (1333 ई.)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (बर्नियर दारा शिकोह के चिकित्सक व दानिशमंद खाँ के संरक्षण में रहे तथा 12 वर्ष भारत भ्रमण किया।) युग्म 2 गलत (सही: निकोलो कोंटी (इटली) — देवराय प्रथम (विजयनगर, 1420 ई.))। युग्म 3 गलत (सही: डोमिंगो पायस (पुर्तगाल) — कृष्णदेवराय (विजयनगर, ~1520 ई.))।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — मुगलकालीन प्रमुख युद्ध] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. चौसा का युद्ध (1539 ई.) : शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय\n2. खानवा युद्ध (1527 ई.) : बाबर बनाम राणा सांगा (मेवाड़)\n3. करनाल का युद्ध (1739 ई.) : नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला'\n4. सामूगढ़ का युद्ध (1658 ई.) : महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":3,"explanation":"युग्म 4 गलत है: 'सामूगढ़ का युद्ध (1658 ई.)' का सही संबंध 'औरंगजेब व मुराद बनाम दारा शिकोह' से है (न कि 'महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ)' से)। मई 1658 में आगरा के निकट सामूगढ़ युद्ध में औरंगजेब की जीत से शाहजहाँ कैद व उत्तराधिकार तय हुआ।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: फतेहपुर सीकरी का बुलंद दरवाजा गुजरात विजय की स्मृति में निर्मित अर्ध-गुंबदाकार ('पिश्तक') प्रवेश द्वार है तथा सलीम चिश्ती का मकबरा बाद में पूर्ण संगमरमर से मढ़ा गया।\nकथन-2: 1665 की पुरंदर संधि द्वारा शिवाजी ने अपने 35 में से 23 किले मुगलों को सौंपे और 12 छोटे किले रखे।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) फतेहपुर सीकरी का बुलंद दरवाजा गुजरात विजय की स्मृति में निर्मित अर्ध-गुंबदाकार ('पिश्तक') प्रवेश द्वार है तथा सलीम चिश्ती का मकबरा बाद में पूर्ण संगमरमर से मढ़ा गया। (2) 1665 की पुरंदर संधि द्वारा शिवाजी ने अपने 35 में से 23 किले मुगलों को सौंपे और 12 छोटे किले रखे।"},
  {"q":"[PSC/CDS युग्म पहचान — ऐतिहासिक युद्ध एवं परिणाम] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. दाशराज्ञ युद्ध (परुष्णी नदी) : नादिर शाह ने मुगल सम्राट मुहम्मद शाह 'रंगीला' की सेना को हराया\n2. खानवा का युद्ध (1527 ई.) : बाबर ने मेवाड़ के राणा सांगा को हराकर 'गाजी' उपाधि ली\n3. करनाल का युद्ध (1739 ई.) : अकबर-बैरम खाँ ने आदिल शाह के सेनापति हेमू (विक्रमादित्य) को हराया\n4. पानीपत का द्वितीय युद्ध (1556 ई.) : चालुक्य नरेश पुलकेशिन द्वितीय ने हर्षवर्धन को हराया","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: 16 मार्च 1527 को खानवा के युद्ध में बाबर ने राणा सांगा के नेतृत्व वाले राजपूत संघ को परास्त किया। (अन्य सही युग्म: दाशराज्ञ युद्ध (परुष्णी नदी)→राजा सुदास (भरत जन) ने दस राजाओं के संघ को पराजित किया, करनाल का युद्ध (1739 ई.)→नादिर शाह ने मुगल सम्राट मुहम्मद शाह 'रंगीला' की सेना को हराया, पानीपत का द्वितीय युद्ध (1556 ई.)→अकबर-बैरम खाँ ने आदिल शाह के सेनापति हेमू (विक्रमादित्य) को हराया)।"},
  {"q":"1658 ई. के किस निर्णायक उत्तराधिकार युद्ध में औरंगजेब ने दारा शिकोह को हराकर दिल्ली की राह खोली?","options":["महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ)","शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय","औरंगजेब व मुराद बनाम दारा शिकोह","बाबर बनाम राणा सांगा (मेवाड़)"],"correct":2,"explanation":"मई 1658 में आगरा के निकट सामूगढ़ युद्ध में औरंगजेब की जीत से शाहजहाँ कैद व उत्तराधिकार तय हुआ। इसके बाद 1659 में देवराई के अंतिम युद्ध में दारा अंतिम रूप से पराजित हुआ।"},
  {"q":"मुगलकालीन वास्तुकला के प्रमुख स्मारक एवं विशेषताएँ — इसके संबंध में 'प्रमुख इमारतें व स्थान' कौन/क्या था?","options":["सुलेह-ए-कुल पर आधारित मित्रता (आमेर के भारमल प्रथम राजपूत संधि 1562, भगवानदास-मानसिंह को उच्च मनसब); मेवाड़ (प्रताप), रणथंभौर, कालिंजर; 'जाट-सवार' रैंक प्रणाली","टोडरमल द्वारा 'आइन-ए-दहसाला' (1580 — 10 वर्षों का औसत); 'मनसबदारी' (मंगोल दशमलव आधारित जात व सवार रैंक); इबादतखाना (1575), महजरनामा (1579), दीन-ए-इलाही (1582)","वजीर/दीवान (वित्त), मीर बख्शी (सैन्य विभाग व मनसब वेतन पत्र 'सरखत'), मीर सामां (शाही कारखाने व रसोई), काजी-उल-कुजात (न्याय)","हुमायूँ का मकबरा (दिल्ली), आगरा किला (अकबर), फतेहपुर सीकरी (बुलंद दरवाजा, पंचमहल, इबादतखाना, सलीम चिश्ती मकबरा), सिकंदरा (अकबर मकबरा — बिना गुंबद), ताजमहल"],"correct":3,"explanation":"ताजमहल के मुख्य वास्तुकार उस्ताद अहमद लाहौरी थे (इमारत पर उस्ताद ईसा खाँ का भी उल्लेख मिलता है) और यह संपूर्ण रूप से सफेद मकराना संगमरमर से बना है।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: मुगलकालीन प्रमुख युद्ध के अंतर्गत 'सामूगढ़ का युद्ध (1658 ई.)' का ऐतिहासिक संबंध 'नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला'' से था।\nकथन-2: फिरोजशाह तुगलक ने गरीब व असहाय नागरिकों की मदद हेतु 'दीवान-ए-खैरात' बनाया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है ('सामूगढ़ का युद्ध (1658 ई.)' का सही संबंध 'औरंगजेब व मुराद बनाम दारा शिकोह' से था — मई 1658 में आगरा के निकट सामूगढ़ युद्ध में औरंगजेब की जीत से शाहजहाँ कैद व उत्तराधिकार तय हुआ।)। कथन-2 सत्य है (फिरोजशाह तुगलक ने गरीब व असहाय नागरिकों की मदद हेतु 'दीवान-ए-खैरात' बनाया।)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. अमर-नायक प्रणाली व विजयनगर आए विदेशी यात्री   B. शेख अहमद सरहिन्दी\nC. मिहिर भोज (गुर्जर-प्रतिहार), गोपाल व धर्मपाल (पाल)   D. एत्मादुद्दौला का मकबरा (आगरा)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["मिहिर भोज (गुर्जर-प्रतिहार), गोपाल व धर्मपाल (पाल)","शेख अहमद सरहिन्दी","एत्मादुद्दौला का मकबरा (आगरा)","अमर-नायक प्रणाली व विजयनगर आए विदेशी यात्री"],"correct":2,"explanation":"मिहिर भोज (गुर्जर-प्रतिहार), गोपाल व धर्मपाल (पाल) (836-885 ई.), अमर-नायक प्रणाली व विजयनगर आए विदेशी यात्री (1565 ई.), शेख अहमद सरहिन्दी (17वीं सदी ई.), एत्मादुद्दौला का मकबरा (आगरा) (1626 ई.)। अतः सबसे अंत में एत्मादुद्दौला का मकबरा (आगरा)।"},
  {"q":"[UPSC Prelims पैटर्न — विदेशी यात्री एवं शासक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. फ्रांस्वा बर्नियर एवं टैवर्नियर : शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68)\n2. फर्नओ नूनिज (पुर्तगाल) : कृष्णदेवराय (विजयनगर, ~1520 ई.)\n3. डोमिंगो पायस (पुर्तगाल) : देवराय द्वितीय (विजयनगर, 1443 ई.)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (बर्नियर दारा शिकोह के चिकित्सक व दानिशमंद खाँ के संरक्षण में रहे तथा 12 वर्ष भारत भ्रमण किया।) युग्म 2 गलत (सही: फर्नओ नूनिज (पुर्तगाल) — अच्युतदेवराय (विजयनगर, ~1535 ई.))। युग्म 3 गलत (सही: डोमिंगो पायस (पुर्तगाल) — कृष्णदेवराय (विजयनगर, ~1520 ई.))।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. दक्कनी सल्तनत व राजवंश के अंतर्गत 'अहमदनगर (निजामशाही, 1490)' का ऐतिहासिक संबंध 'फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद' से था।\n2. सूफी सिलसिले एवं शब्दावली के अंतर्गत 'शेख अहमद सरहिन्दी' का ऐतिहासिक संबंध 'शेख बहाउद्दीन जकरिया (मुल्तान)' से था।\n3. सल्तनत विभाग एवं सुल्तान के अंतर्गत 'दीवान-ए-अमीर कोही' का ऐतिहासिक संबंध 'असहायों व गरीब कन्याओं की सहायता का दान विभाग (फिरोज तुगलक)' से था।\n4. 1539 ई. में बक्सर के निकट चौसा के युद्ध में शेरशाह सूरी ने हुमायूँ को पराजित किया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (1539 ई. में बक्सर के निकट चौसा के युद्ध में शेरशाह सूरी ने हुमायूँ को पराजित किया।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: नूरजहाँ ने अपने पिता मिर्जा गियास बेग की स्मृति में यमुना तट पर एत्मादुद्दौला का मकबरा बनवाया।\nकथन-2: विजयनगर साम्राज्य पर शासन करने वाले चार राजवंशों का सही कालानुक्रम तुलुव -> संगम -> सालुव -> अराविदु था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (नूरजहाँ ने अपने पिता मिर्जा गियास बेग की स्मृति में यमुना तट पर एत्मादुद्दौला का मकबरा बनवाया।)। कथन-2 गलत है — विजयनगर पर राजवंशों का सही कालानुक्रम संगम (1336-1485) -> सालुव (1485-1505) -> तुलुव (1505-1570) -> अराविदु (1570-1650) था।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: शाहजहाँ ने बलख-बदख्शां का मध्य एशिया अभियान किया, पुर्तगालियों को 1632 में हुगली से खदेड़ा और अहमदनगर (1633) को पूरी तरह मुगल साम्राज्य में मिलाया।\nकथन-2: भक्ति मत एवं प्रवर्तक के अंतर्गत 'विशिष्टाद्वैतवाद' का ऐतिहासिक संबंध 'माध्वाचार्य (13वीं सदी, उडुपी)' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (शाहजहाँ ने बलख-बदख्शां का मध्य एशिया अभियान किया, पुर्तगालियों को 1632 में हुगली से खदेड़ा और अहमदनगर (1633) को पूरी तरह मुगल साम्राज्य में मिलाया।)। कथन-2 गलत है — 'विशिष्टाद्वैतवाद' का सही संबंध 'रामानुजाचार्य (11वीं सदी, श्रीरंगम)' से था — रामानुजाचार्य ने ब्रह्म को सगुण मानते हुए भक्ति (प्रपत्ति) को मोक्ष का सर्वश्रेष्ठ मार्ग बताया।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. मुगलकालीन प्रशासनिक शब्दावली के अंतर्गत 'हुण्डी' का ऐतिहासिक संबंध '1-2 वर्ष उर्वरता बढ़ाने हेतु खाली छोड़ी गई भूमि' से था।\n2. नूरजहाँ ने अपने पिता मिर्जा गियास बेग की स्मृति में यमुना तट पर एत्मादुद्दौला का मकबरा बनवाया।\n3. 712 ई. में मुहम्मद बिन कासिम ने सिन्ध विजय के बाद सभी ब्राह्मणों, विधवाओं व अपंगों पर भी अनिवार्य रूप से जजिया कर लगा दिया था।\n4. मध्यकालीन स्थापत्य एवं निर्माता के अंतर्गत 'सासाराम झील मकबरा' का ऐतिहासिक संबंध 'नूरजहाँ (जहाँगीर काल, 1626)' से था।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":1,"explanation":"कथन 2 सत्य है (नूरजहाँ ने अपने पिता मिर्जा गियास बेग की स्मृति में यमुना तट पर एत्मादुद्दौला का मकबरा बनवाया।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. मिहिर भोज (गुर्जर-प्रतिहार), गोपाल व धर्मपाल (पाल)   B. सर थॉमस रो (ब्रिटेन)\nC. मुहम्मद बिन तुगलक की पांच महत्वाकांक्षी योजनाएँ   D. खानवा युद्ध (1527 ई.)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["मिहिर भोज (गुर्जर-प्रतिहार), गोपाल व धर्मपाल (पाल)","खानवा युद्ध (1527 ई.)","सर थॉमस रो (ब्रिटेन)","मुहम्मद बिन तुगलक की पांच महत्वाकांक्षी योजनाएँ"],"correct":2,"explanation":"मिहिर भोज (गुर्जर-प्रतिहार), गोपाल व धर्मपाल (पाल) (836-885 ई.), मुहम्मद बिन तुगलक की पांच महत्वाकांक्षी योजनाएँ (1325-1351 ई.), खानवा युद्ध (1527 ई.) (1527 ई.), सर थॉमस रो (ब्रिटेन) (1615 ई.)। अतः सबसे अंत में सर थॉमस रो (ब्रिटेन)।"},
  {"q":"ऐतिहासिक संदर्भ में 'हुमायूँ का मकबरा (दिल्ली), आगरा किला (अकबर), फतेहपुर सीकरी (बुलंद दरवाजा, पंचमहल, इबादतखाना, सलीम चिश्ती मकबरा), सिकंदरा (अकबर मकबरा — बिना गुंबद), ताजमहल' (प्रमुख इमारतें व स्थान) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["अकबर की दहसाला व्यवस्था, मनसबदारी एवं सुलह-ए-कुल","मुगलकालीन केंद्रीय व प्रांतीय प्रशासन तथा राजस्व पद","अकबर की राजपूत नीति, नवरत्न व मनसबदारी के नियम","मुगलकालीन वास्तुकला के प्रमुख स्मारक एवं विशेषताएँ"],"correct":3,"explanation":"ताजमहल के मुख्य वास्तुकार उस्ताद अहमद लाहौरी थे (इमारत पर उस्ताद ईसा खाँ का भी उल्लेख मिलता है) और यह संपूर्ण रूप से सफेद मकराना संगमरमर से बना है।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक युद्ध एवं परिणाम] निम्नलिखित युग्मों पर विचार कीजिए:\n1. चौसा का युद्ध (1539 ई.) : शेर खान (शेरशाह सूरी) ने हुमायूँ को पराजित कर 'शेरशाह' उपाधि धारण की\n2. तालीकोटा का युद्ध (1565 ई.) : अहमद शाह अब्दाली ने सदाशिवराव भाऊ के नेतृत्व वाली मराठा सेना को हराया\n3. पानीपत का तृतीय युद्ध (1761 ई.) : राष्ट्रकूट कृष्ण तृतीय ने चोल शासक परांतक प्रथम के पुत्र राजादित्य को हराया\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (1539 ई. में बक्सर के निकट चौसा के युद्ध में शेरशाह सूरी ने हुमायूँ को पराजित किया।) युग्म 2 गलत (सही: तालीकोटा का युद्ध (1565 ई.) — दक्कनी सल्तनतों के संघ ने विजयनगर के रामराय को पराजित किया)। युग्म 3 गलत (सही: पानीपत का तृतीय युद्ध (1761 ई.) — अहमद शाह अब्दाली ने सदाशिवराव भाऊ के नेतृत्व वाली मराठा सेना को हराया)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — विदेशी यात्री एवं शासक] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. फ्रांस्वा बर्नियर एवं टैवर्नियर : बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)\n2. डोमिंगो पायस (पुर्तगाल) : कृष्णदेवराय (विजयनगर, ~1520 ई.)\n3. अब्दुर रज्जाक (फारस/समरकंद) : देवराय द्वितीय (विजयनगर, 1443 ई.)\n4. निकोलो कोंटी (इटली) : देवराय प्रथम (विजयनगर, 1420 ई.)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":0,"explanation":"युग्म 1 गलत है: 'फ्रांस्वा बर्नियर एवं टैवर्नियर' का सही संबंध 'शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68)' से है (न कि 'बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)' से)। बर्नियर दारा शिकोह के चिकित्सक व दानिशमंद खाँ के संरक्षण में रहे तथा 12 वर्ष भारत भ्रमण किया।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. विदेशी यात्री एवं शासक के अंतर्गत 'सर थॉमस रो (ब्रिटेन)' का ऐतिहासिक संबंध 'शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68)' से था।\n2. 1675 ई. में औरंगजेब के जबरन धर्मांतरण के विरोध पर दिल्ली के चाँदनी चौक में गुरु तेग बहादुर ने बलिदान दिया।\n3. बलबन ने मंगोल संकट से निपटने हेतु केंद्रीय सैन्य विभाग 'दीवान-ए-अर्ज' स्थापित किया।\n4. कृष्णदेवराय का शासनकाल तेलुगु साहित्य का 'क्लासिकल युग' माना जाता है; उन्होंने पुर्तगालियों (गवर्नर अल्बुकर्क) से अरबी घोड़ों के व्यापार हेतु मैत्रीपूर्ण संबंध रखे।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":0,"explanation":"कथन 1 असत्य है। सुधार: 'सर थॉमस रो (ब्रिटेन)' का सही संबंध 'जहाँगीर (1615-1619 ई.)' से था — थॉमस रो ने जहाँगीर से अजमेर व मांडू में भेंट कर ब्रिटिश ईस्ट इंडिया कंपनी को व्यापारिक छूट दिलाई।"},
  {"q":"'मुगलकालीन वास्तुकला के प्रमुख स्मारक एवं विशेषताएँ' के ऐतिहासिक संदर्भ में 'तकनीकी शिल्प' निम्नलिखित में से क्या है?","options":["प्रथम श्रेणी (सवार = जात), द्वितीय श्रेणी (सवार >= जात/2), तृतीय श्रेणी (सवार < जात/2); 'ख्वाजा सरा' व 'मीर-ए-बहर' नौका विभाग","'चारबाग', 'पित्रादुरा' (संगमरमर में कीमती रत्नों की जड़ाई — एत्मादुद्दौला व ताजमहल), 'पिश्तक' (विशाल मेहराबी प्रवेशद्वार), अर्ध-प्याजी गुंबद","सूबा (सूबेदार व प्रांतीय दीवान नियंत्रण संतुलन), सरकार/जिला (फौजदार व अमलगुजार), परगना (शिकदार व आमिल), ग्राम (मुकद्दम व पटवारी)","अबुल फजल ('अकबरनामा'/'आइन-ए-अकबरी'), फैजी, तानसेन, बीरबल (प्रथम व एकमात्र हिंदू जिसने दीन-ए-इलाही स्वीकार किया), टोडरमल, मानसिंह, रहीम, फकीर अजीउद्दीन, मुल्ला दो प्याजा"],"correct":1,"explanation":"ताजमहल के मुख्य वास्तुकार उस्ताद अहमद लाहौरी थे (इमारत पर उस्ताद ईसा खाँ का भी उल्लेख मिलता है) और यह संपूर्ण रूप से सफेद मकराना संगमरमर से बना है।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: दारा शिकोह ने समूचे सिख 'आदि ग्रंथ' का तुर्की भाषा में 'मज्म-उल-बहरीन' नाम से अनुवाद कर औरंगजेब को भेंट किया।\nकथन-2: भाई लहणा (गुरु अंगद देव) ने गुरु नानक के उपदेशों के लिए गुरुमुखी लिपि को मानक रूप दिया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है (दारा शिकोह ने फारसी भाषा में 52 उपनिषदों का अनुवाद 'सिर्र-ए-अकबर' (महान रहस्य) नाम से तथा स्वतंत्र तुलनात्मक ग्रंथ 'मज्म-उल-बहरीन' (दो समुद्रों का संगम) लिखा।)। कथन-2 सत्य है (भाई लहणा (गुरु अंगद देव) ने गुरु नानक के उपदेशों के लिए गुरुमुखी लिपि को मानक रूप दिया।)।"},
  {"q":"[UPSC Prelims पैटर्न — विदेशी यात्री एवं शासक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. सर थॉमस रो (ब्रिटेन) : जहाँगीर (1615-1619 ई.)\n2. अब्दुर रज्जाक (फारस/समरकंद) : बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)\n3. अफनासी निकितिन (रूस) : अच्युतदेवराय (विजयनगर, ~1535 ई.)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (थॉमस रो ने जहाँगीर से अजमेर व मांडू में भेंट कर ब्रिटिश ईस्ट इंडिया कंपनी को व्यापारिक छूट दिलाई।) युग्म 2 गलत (सही: अब्दुर रज्जाक (फारस/समरकंद) — देवराय द्वितीय (विजयनगर, 1443 ई.))। युग्म 3 गलत (सही: अफनासी निकितिन (रूस) — बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.))।"},
  {"q":"ऐतिहासिक संदर्भ में 'टोडरमल द्वारा 'आइन-ए-दहसाला' (1580 — 10 वर्षों का औसत); 'मनसबदारी' (मंगोल दशमलव आधारित जात व सवार रैंक); इबादतखाना (1575), महजरनामा (1579), दीन-ए-इलाही (1582)' (प्रशासनिक व धार्मिक सुधार) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["मुगलकालीन केंद्रीय व प्रांतीय प्रशासन तथा राजस्व पद","मुगलकालीन वास्तुकला के प्रमुख स्मारक एवं विशेषताएँ","अकबर की दहसाला व्यवस्था, मनसबदारी एवं सुलह-ए-कुल","अकबर की राजपूत नीति, नवरत्न व मनसबदारी के नियम"],"correct":2,"explanation":"अकबर के शासन में 'मदद-ए-माअश' (सयूरगल) भूमि विद्वानों व धार्मिक व्यक्तियों को करमुक्त अनुदान में दी जाती थी। भूमि 4 वर्गों (पोलज, परती, चाचर, बंजर) में बँटी थी।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. मध्यकालीन स्थापत्य एवं निर्माता के अंतर्गत 'एत्मादुद्दौला का मकबरा (आगरा)' का ऐतिहासिक संबंध 'औरंगजेब (पुत्र आजम शाह द्वारा रबिया-उद-दुर्रानी हेतु)' से था।\n2. बर्नियर दारा शिकोह के चिकित्सक व दानिशमंद खाँ के संरक्षण में रहे तथा 12 वर्ष भारत भ्रमण किया।\n3. सूफी सिलसिले एवं शब्दावली के अंतर्गत 'सुहरावर्दी सिलसिला (भारत)' का ऐतिहासिक संबंध 'नक्शबंदी सिलसिला ('वहदत-उल-शुहूद' सिद्धांत)' से था।\n4. कबीर और गुरु नानक दोनों अवतारवाद व मूर्तिपूजा के प्रबल सगुण समर्थक थे और केवल संस्कृत भाषा में उपदेश देते थे।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":1,"explanation":"कथन 2 सत्य है (बर्नियर दारा शिकोह के चिकित्सक व दानिशमंद खाँ के संरक्षण में रहे तथा 12 वर्ष भारत भ्रमण किया।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. सामूगढ़ का युद्ध (1658 ई.)   B. बीजापुर (आदिलशाही, 1489)\nC. पद्मावत (अवधी, 1540)   D. बहमनी साम्राज्य, महमूद गवां एवं पांच दक्कनी सल्तनतें\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["बहमनी साम्राज्य, महमूद गवां एवं पांच दक्कनी सल्तनतें","पद्मावत (अवधी, 1540)","बीजापुर (आदिलशाही, 1489)","सामूगढ़ का युद्ध (1658 ई.)"],"correct":3,"explanation":"बहमनी साम्राज्य, महमूद गवां एवं पांच दक्कनी सल्तनतें (1347 ई.), बीजापुर (आदिलशाही, 1489) (1489 ई.), पद्मावत (अवधी, 1540) (1540 ई.), सामूगढ़ का युद्ध (1658 ई.) (1658 ई.)। अतः सबसे अंत में सामूगढ़ का युद्ध (1658 ई.)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. फ्रांस्वा बर्नियर एवं टैवर्नियर   B. कृष्णदेवराय (तुलुव वंश) एवं अष्टदिग्गज\nC. सुहरावर्दी सिलसिला (भारत)   D. फतवा-ए-जहाँदारी\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["कृष्णदेवराय (तुलुव वंश) एवं अष्टदिग्गज","सुहरावर्दी सिलसिला (भारत)","फ्रांस्वा बर्नियर एवं टैवर्नियर","फतवा-ए-जहाँदारी"],"correct":2,"explanation":"सुहरावर्दी सिलसिला (भारत) (13वीं सदी ई.), फतवा-ए-जहाँदारी (14वीं सदी ई.), कृष्णदेवराय (तुलुव वंश) एवं अष्टदिग्गज (1509-1529 ई.), फ्रांस्वा बर्नियर एवं टैवर्नियर (1658 ई.)। अतः सबसे अंत में फ्रांस्वा बर्नियर एवं टैवर्नियर।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: बर्नियर दारा शिकोह के चिकित्सक व दानिशमंद खाँ के संरक्षण में रहे तथा 12 वर्ष भारत भ्रमण किया।\nकथन-2: मध्यकालीन स्थापत्य एवं निर्माता के अंतर्गत 'अलाई दरवाजा (1311 ई.)' का ऐतिहासिक संबंध 'ढलवाँ दीवारें ('सलामी'/Batter) व अष्टकोणीय लाल-सफेद मकबरा' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (बर्नियर दारा शिकोह के चिकित्सक व दानिशमंद खाँ के संरक्षण में रहे तथा 12 वर्ष भारत भ्रमण किया।)। कथन-2 गलत है — 'अलाई दरवाजा (1311 ई.)' का सही संबंध 'अलाउद्दीन खिलजी' से था — अलाउद्दीन खिलजी ने कुव्वत-उल-इस्लाम मस्जिद के प्रवेश द्वार के रूप में अलाई दरवाजा बनवाया।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. ऐतिहासिक युद्ध एवं परिणाम के अंतर्गत 'खानवा का युद्ध (1527 ई.)' का ऐतिहासिक संबंध 'शेर खान (शेरशाह सूरी) ने हुमायूँ को पराजित कर 'शेरशाह' उपाधि धारण की' से था।\n2. चिश्तियों के विपरीत शेख बहाउद्दीन जकरिया ने सुल्तान इल्तुतमिश से 'शेख-उल-इस्लाम' पद व धन स्वीकार किया।\n3. रामानंद ने भक्ति के द्वार सभी जातियों व स्त्रियों के लिए खोले; उनके शिष्यों में कबीर (जुलाहा), रैदास (चर्मकार), धन्ना (जाट), सेन (नाई) व पीपा शामिल थे।\n4. तक्कोलम के युद्ध में राष्ट्रकूट राजा कृष्ण तृतीय ने चोलों को करारी हार दी।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":0,"explanation":"कथन 1 असत्य है। सुधार: 'खानवा का युद्ध (1527 ई.)' का सही संबंध 'बाबर ने मेवाड़ के राणा सांगा को हराकर 'गाजी' उपाधि ली' से था — 16 मार्च 1527 को खानवा के युद्ध में बाबर ने राणा सांगा के नेतृत्व वाले राजपूत संघ को परास्त किया।"},
  {"q":"[PSC/CDS युग्म पहचान — ऐतिहासिक युद्ध एवं परिणाम] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. तालीकोटा का युद्ध (1565 ई.) : सिकंदर ने पंजाब के शासक पोरस को पराजित कर मैत्री की\n2. हाइडेस्पीज का युद्ध (326 ई.पू.) : पृथ्वीराज चौहान तृतीय ने मुहम्मद गौरी को पराजित किया\n3. चौसा का युद्ध (1539 ई.) : शेर खान (शेरशाह सूरी) ने हुमायूँ को पराजित कर 'शेरशाह' उपाधि धारण की\n4. तराइन का प्रथम युद्ध (1191 ई.) : राजा सुदास (भरत जन) ने दस राजाओं के संघ को पराजित किया","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: 1539 ई. में बक्सर के निकट चौसा के युद्ध में शेरशाह सूरी ने हुमायूँ को पराजित किया। (अन्य सही युग्म: तालीकोटा का युद्ध (1565 ई.)→दक्कनी सल्तनतों के संघ ने विजयनगर के रामराय को पराजित किया, हाइडेस्पीज का युद्ध (326 ई.पू.)→सिकंदर ने पंजाब के शासक पोरस को पराजित कर मैत्री की, तराइन का प्रथम युद्ध (1191 ई.)→पृथ्वीराज चौहान तृतीय ने मुहम्मद गौरी को पराजित किया)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. पानीपत का द्वितीय युद्ध (1556 ई.)   B. फतवा-ए-जहाँदारी\nC. फ्रांस्वा बर्नियर एवं टैवर्नियर   D. शेख अहमद सरहिन्दी\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["पानीपत का द्वितीय युद्ध (1556 ई.)","फतवा-ए-जहाँदारी","शेख अहमद सरहिन्दी","फ्रांस्वा बर्नियर एवं टैवर्नियर"],"correct":3,"explanation":"फतवा-ए-जहाँदारी (14वीं सदी ई.), पानीपत का द्वितीय युद्ध (1556 ई.) (1556 ई.), शेख अहमद सरहिन्दी (17वीं सदी ई.), फ्रांस्वा बर्नियर एवं टैवर्नियर (1658 ई.)। अतः सबसे अंत में फ्रांस्वा बर्नियर एवं टैवर्नियर।"},
  {"q":"[UPSC/PCS सूची सुमेलन — मध्यकालीन स्थापत्य एवं निर्माता] सूची-I को सूची-II से सुमेलित कीजिए:\nA. एत्मादुद्दौला का मकबरा (आगरा)   |   1. शेरशाह सूरी\nB. गयासुद्दीन तुगलक मकबरा   |   2. भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन)\nC. सिकंदर लोदी का मकबरा (1517)   |   3. नूरजहाँ (जहाँगीर काल, 1626)\nD. सासाराम झील मकबरा   |   4. ढलवाँ दीवारें ('सलामी'/Batter) व अष्टकोणीय लाल-सफेद मकबरा","options":["A-3, B-2, C-4, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2"],"correct":1,"explanation":"सही सुमेलन: एत्मादुद्दौला का मकबरा (आगरा) (नूरजहाँ (जहाँगीर काल, 1626)), गयासुद्दीन तुगलक मकबरा (ढलवाँ दीवारें ('सलामी'/Batter) व अष्टकोणीय लाल-सफेद मकबरा), सिकंदर लोदी का मकबरा (1517) (भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन)), सासाराम झील मकबरा (शेरशाह सूरी)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. किताब-ए-नवरस   B. अफनासी निकितिन (रूस)\nC. सामूगढ़ का युद्ध (1658 ई.)   D. अब्दुर रज्जाक (फारस/समरकंद)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["अफनासी निकितिन (रूस)","अब्दुर रज्जाक (फारस/समरकंद)","किताब-ए-नवरस","सामूगढ़ का युद्ध (1658 ई.)"],"correct":3,"explanation":"अब्दुर रज्जाक (फारस/समरकंद) (1443 ई.), अफनासी निकितिन (रूस) (1470 ई.), किताब-ए-नवरस (1600 ई.), सामूगढ़ का युद्ध (1658 ई.) (1658 ई.)। अतः सबसे अंत में सामूगढ़ का युद्ध (1658 ई.)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. मध्यकालीन ग्रंथ एवं लेखक के अंतर्गत 'तबकात-ए-नासिरी' का ऐतिहासिक संबंध 'जियाउद्दीन बरनी' से था।\n2. फतेहपुर सीकरी का बुलंद दरवाजा गुजरात विजय की स्मृति में निर्मित अर्ध-गुंबदाकार ('पिश्तक') प्रवेश द्वार है तथा सलीम चिश्ती का मकबरा बाद में पूर्ण संगमरमर से मढ़ा गया।\n3. सिख गुरु परंपरा के अंतर्गत 'गुरु हरगोबिंद (छठे गुरु)' का ऐतिहासिक संबंध 'धार्मिक स्वतंत्रता हेतु 1675 ई. में दिल्ली (शीशगंज) में शहादत' से था।\n4. मुगलकालीन प्रमुख युद्ध के अंतर्गत 'खानवा युद्ध (1527 ई.)' का ऐतिहासिक संबंध 'शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय' से था।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":1,"explanation":"कथन 2 सत्य है (फतेहपुर सीकरी का बुलंद दरवाजा गुजरात विजय की स्मृति में निर्मित अर्ध-गुंबदाकार ('पिश्तक') प्रवेश द्वार है तथा सलीम चिश्ती का मकबरा बाद में पूर्ण संगमरमर से मढ़ा गया।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. छत्रपति शिवाजी महाराज: स्वराज, पुरंदर संधि व अष्टप्रधान   B. पानीपत का तृतीय युद्ध (1761 ई.)\nC. हल्दीघाटी युद्ध (1576 ई.)   D. सुहरावर्दी सिलसिला (भारत)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["सुहरावर्दी सिलसिला (भारत)","छत्रपति शिवाजी महाराज: स्वराज, पुरंदर संधि व अष्टप्रधान","पानीपत का तृतीय युद्ध (1761 ई.)","हल्दीघाटी युद्ध (1576 ई.)"],"correct":2,"explanation":"सुहरावर्दी सिलसिला (भारत) (13वीं सदी ई.), हल्दीघाटी युद्ध (1576 ई.) (1576 ई.), छत्रपति शिवाजी महाराज: स्वराज, पुरंदर संधि व अष्टप्रधान (1674 ई.), पानीपत का तृतीय युद्ध (1761 ई.) (1761 ई.)। अतः सबसे अंत में पानीपत का तृतीय युद्ध (1761 ई.)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: मुगलकालीन प्रमुख युद्ध के अंतर्गत 'सामूगढ़ का युद्ध (1658 ई.)' का ऐतिहासिक संबंध 'नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला'' से था।\nकथन-2: मुहम्मद बिन तुगलक ने अपनी सांकेतिक मुद्रा का निर्माण कठोर राजकीय टकसाल नियंत्रण के साथ केवल शुद्ध चाँदी से कराया था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'सामूगढ़ का युद्ध (1658 ई.)' का सही संबंध 'औरंगजेब व मुराद बनाम दारा शिकोह' से था — मई 1658 में आगरा के निकट सामूगढ़ युद्ध में औरंगजेब की जीत से शाहजहाँ कैद व उत्तराधिकार तय हुआ। (2) मुहम्मद बिन तुगलक ने चाँदी की वैश्विक कमी के कारण ताँबे/काँसे की सांकेतिक मुद्रा चलाई, किंतु नकली सिक्कों की ढलाई न रोक पाने के कारण योजना विफल हुई।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: सिकंदरा (आगरा) में स्थित सम्राट अकबर का मकबरा अपने विशाल सुनहरे प्याजनुमा गुंबद व पूर्णतः हिंदू शिखर शैली के अभाव के लिए प्रसिद्ध है।\nकथन-2: इक्ता प्रणाली (इल्तुतमिश द्वारा सुसंगठित) के अंतर्गत भूमि का हस्तांतरणीय राजस्व आवंटन सैन्य-नागरिक अधिकारियों (इक्तादार/मुक्ता/वली) को वेतन के बदले किया जाता था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है (अकबर के मकबरे (सिकंदरा) की सबसे अनोखी विशेषता यह है कि वह पंचमंजिला पिरामिडनुमा है और उसमें कोई गुंबद (Domeless) नहीं है।)। कथन-2 सत्य है (इक्ता प्रणाली (इल्तुतमिश द्वारा सुसंगठित) के अंतर्गत भूमि का हस्तांतरणीय राजस्व आवंटन सैन्य-नागरिक अधिकारियों (इक्तादार/मुक्ता/वली) को वेतन के बदले किया जाता था।)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. सर थॉमस रो (ब्रिटेन)   B. पुरंदर की संधि (1665 ई.)\nC. छत्रपति शिवाजी महाराज: स्वराज, पुरंदर संधि व अष्टप्रधान   D. पेशवाओं का उत्कर्ष एवं पानीपत का तृतीय युद्ध (1761)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["छत्रपति शिवाजी महाराज: स्वराज, पुरंदर संधि व अष्टप्रधान","पुरंदर की संधि (1665 ई.)","सर थॉमस रो (ब्रिटेन)","पेशवाओं का उत्कर्ष एवं पानीपत का तृतीय युद्ध (1761)"],"correct":2,"explanation":"सर थॉमस रो (ब्रिटेन) (1615 ई.), पुरंदर की संधि (1665 ई.) (1665 ई.), छत्रपति शिवाजी महाराज: स्वराज, पुरंदर संधि व अष्टप्रधान (1674 ई.), पेशवाओं का उत्कर्ष एवं पानीपत का तृतीय युद्ध (1761) (1761 ई.)। अतः सर्वप्रथम सर थॉमस रो (ब्रिटेन)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. विजयनगर साम्राज्य पर शासन करने वाले चार राजवंशों का सही कालानुक्रम तुलुव -> संगम -> सालुव -> अराविदु था।\n2. जहाँगीर का काल मुगल चित्रकला का चरमोत्कर्ष ('स्वर्ण युग') था; वह चित्र देखकर प्रत्येक चित्रकार का नाम पहचानने का दावा करता था और उसने 'आगा रजा' के अधीन चित्रशाला खोली।\n3. मुगलकालीन प्रशासनिक शब्दावली के अंतर्गत 'हुण्डी' का ऐतिहासिक संबंध '1-2 वर्ष उर्वरता बढ़ाने हेतु खाली छोड़ी गई भूमि' से था।\n4. 712 ई. में मुहम्मद बिन कासिम ने सिन्ध विजय के बाद सभी ब्राह्मणों, विधवाओं व अपंगों पर भी अनिवार्य रूप से जजिया कर लगा दिया था।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":1,"explanation":"कथन 2 सत्य है (जहाँगीर का काल मुगल चित्रकला का चरमोत्कर्ष ('स्वर्ण युग') था; वह चित्र देखकर प्रत्येक चित्रकार का नाम पहचानने का दावा करता था और उसने 'आगा रजा' के अधीन चित्रशाला खोली।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. तैमूर आक्रमण (1398), सैय्यद वंश एवं लोदी राजवंश   B. एकशरण संप्रदाय (असम)\nC. अकबर की दहसाला व्यवस्था, मनसबदारी एवं सुलह-ए-कुल   D. किताब-उल-हिन्द\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["किताब-उल-हिन्द","एकशरण संप्रदाय (असम)","तैमूर आक्रमण (1398), सैय्यद वंश एवं लोदी राजवंश","अकबर की दहसाला व्यवस्था, मनसबदारी एवं सुलह-ए-कुल"],"correct":3,"explanation":"किताब-उल-हिन्द (11वीं सदी ई.), एकशरण संप्रदाय (असम) (15वीं-16वीं सदी), तैमूर आक्रमण (1398), सैय्यद वंश एवं लोदी राजवंश (1504 ई.), अकबर की दहसाला व्यवस्था, मनसबदारी एवं सुलह-ए-कुल (1580 ई.)। अतः सबसे अंत में अकबर की दहसाला व्यवस्था, मनसबदारी एवं सुलह-ए-कुल।"},
  {"q":"'अकबर की दहसाला व्यवस्था, मनसबदारी एवं सुलह-ए-कुल' के ऐतिहासिक संदर्भ में 'अकबर के नवरत्न' निम्नलिखित में से क्या है?","options":["'चारबाग', 'पित्रादुरा' (संगमरमर में कीमती रत्नों की जड़ाई — एत्मादुद्दौला व ताजमहल), 'पिश्तक' (विशाल मेहराबी प्रवेशद्वार), अर्ध-प्याजी गुंबद","सूबा (सूबेदार व प्रांतीय दीवान नियंत्रण संतुलन), सरकार/जिला (फौजदार व अमलगुजार), परगना (शिकदार व आमिल), ग्राम (मुकद्दम व पटवारी)","अबुल फजल ('अकबरनामा'/'आइन-ए-अकबरी'), फैजी, तानसेन, बीरबल (प्रथम व एकमात्र हिंदू जिसने दीन-ए-इलाही स्वीकार किया), टोडरमल, मानसिंह, रहीम, फकीर अजीउद्दीन, मुल्ला दो प्याजा","प्रथम श्रेणी (सवार = जात), द्वितीय श्रेणी (सवार >= जात/2), तृतीय श्रेणी (सवार < जात/2); 'ख्वाजा सरा' व 'मीर-ए-बहर' नौका विभाग"],"correct":2,"explanation":"अकबर के शासन में 'मदद-ए-माअश' (सयूरगल) भूमि विद्वानों व धार्मिक व्यक्तियों को करमुक्त अनुदान में दी जाती थी। भूमि 4 वर्गों (पोलज, परती, चाचर, बंजर) में बँटी थी।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: मध्यकालीन स्थापत्य एवं निर्माता के अंतर्गत 'गयासुद्दीन तुगलक मकबरा' का ऐतिहासिक संबंध 'भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन)' से था।\nकथन-2: औरंगजेब ने हिंदू अधिकारियों की संख्या शून्य कर दी और बीजापुर व गोलकुंडा से मित्रता कर दक्कन में स्थायी शांति कायम रखी।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'गयासुद्दीन तुगलक मकबरा' का सही संबंध 'ढलवाँ दीवारें ('सलामी'/Batter) व अष्टकोणीय लाल-सफेद मकबरा' से था — तुगलकाबाद में कृत्रिम झील के मध्य बनी इस इमारत में किले जैसी ढलवाँ दीवारें सुरक्षा हेतु बनाई गईं। (2) औरंगजेब के काल में राजपूत-मराठा भर्ती के कारण हिंदू मनसबदारों का अनुपात सर्वाधिक (लगभग 33%) था; उसने बीजापुर-गोलकुंडा जीतकर प्रत्यक्ष मिलाए (दक्कन का नासूर)।"},
  {"q":"इंग्लैंड के सम्राट जेम्स प्रथम का राजदूत सर थॉमस रो किस मुगल बादशाह के दरबार में आया?","options":["देवराय द्वितीय (विजयनगर, 1443 ई.)","जहाँगीर (1615-1619 ई.)","देवराय प्रथम (विजयनगर, 1420 ई.)","कृष्णदेवराय (विजयनगर, ~1520 ई.)"],"correct":1,"explanation":"थॉमस रो ने जहाँगीर से अजमेर व मांडू में भेंट कर ब्रिटिश ईस्ट इंडिया कंपनी को व्यापारिक छूट दिलाई। उससे पहले 1608 में कैप्टन विलियम हॉकिन्स भी जहाँगीर के दरबार आए थे ('इंग्लिश खान' उपाधि)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. गुरु रामदास (चौथे गुरु)   B. अकबर की दहसाला व्यवस्था, मनसबदारी एवं सुलह-ए-कुल\nC. इब्नबतूता (मोरक्को)   D. गोलकुंडा (कुतुबशाही, 1512/18)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["अकबर की दहसाला व्यवस्था, मनसबदारी एवं सुलह-ए-कुल","गोलकुंडा (कुतुबशाही, 1512/18)","गुरु रामदास (चौथे गुरु)","इब्नबतूता (मोरक्को)"],"correct":0,"explanation":"इब्नबतूता (मोरक्को) (1333 ई.), गोलकुंडा (कुतुबशाही, 1512/18) (1518 ई.), गुरु रामदास (चौथे गुरु) (1577 ई.), अकबर की दहसाला व्यवस्था, मनसबदारी एवं सुलह-ए-कुल (1580 ई.)। अतः सबसे अंत में अकबर की दहसाला व्यवस्था, मनसबदारी एवं सुलह-ए-कुल।"},
  {"q":"[UPSC / CDS कालानुक्रम] निम्नलिखित ऐतिहासिक घटनाओं का प्राचीनतम से नवीनतम सही कालानुक्रम क्या है?\n1. रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति)   2. जहाँगीर (सलीम): न्याय की जंजीर, चित्रकला का स्वर्ण युग व नूरजहाँ जुंटा\n3. बीजापुर (आदिलशाही, 1489)   4. तराइन का प्रथम युद्ध (1191 ई.)","options":["रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति) → तराइन का प्रथम युद्ध (1191 ई.) → बीजापुर (आदिलशाही, 1489) → जहाँगीर (सलीम): न्याय की जंजीर, चित्रकला का स्वर्ण युग व नूरजहाँ जुंटा","तराइन का प्रथम युद्ध (1191 ई.) → बीजापुर (आदिलशाही, 1489) → रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति) → जहाँगीर (सलीम): न्याय की जंजीर, चित्रकला का स्वर्ण युग व नूरजहाँ जुंटा","तराइन का प्रथम युद्ध (1191 ई.) → रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति) → बीजापुर (आदिलशाही, 1489) → जहाँगीर (सलीम): न्याय की जंजीर, चित्रकला का स्वर्ण युग व नूरजहाँ जुंटा","तराइन का प्रथम युद्ध (1191 ई.) → रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति) → जहाँगीर (सलीम): न्याय की जंजीर, चित्रकला का स्वर्ण युग व नूरजहाँ जुंटा → बीजापुर (आदिलशाही, 1489)"],"correct":2,"explanation":"सही कालानुक्रम: तराइन का प्रथम युद्ध (1191 ई.) (1191 ई.), रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति) (1266-1287 ई.), बीजापुर (आदिलशाही, 1489) (1489 ई.), जहाँगीर (सलीम): न्याय की जंजीर, चित्रकला का स्वर्ण युग व नूरजहाँ जुंटा (1605-1627 ई.)"},
  {"q":"1527 ई. में 'खानवा के युद्ध' में बाबर ने किस राजपूत महासंघ के नेतृत्वकर्ता को पराजित किया?","options":["सिकंदर ने पंजाब के शासक पोरस को पराजित कर मैत्री की","राजा सुदास (भरत जन) ने दस राजाओं के संघ को पराजित किया","चालुक्य नरेश पुलकेशिन द्वितीय ने हर्षवर्धन को हराया","बाबर ने मेवाड़ के राणा सांगा को हराकर 'गाजी' उपाधि ली"],"correct":3,"explanation":"16 मार्च 1527 को खानवा के युद्ध में बाबर ने राणा सांगा के नेतृत्व वाले राजपूत संघ को परास्त किया। इसी युद्ध से पूर्व बाबर ने 'जिहाद' का नारा दिया और सैनिकों पर तमगा कर समाप्त किया।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — ऐतिहासिक युद्ध एवं परिणाम] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. तराइन का प्रथम युद्ध (1191 ई.) : पृथ्वीराज चौहान तृतीय ने मुहम्मद गौरी को पराजित किया\n2. खानवा का युद्ध (1527 ई.) : दक्कनी सल्तनतों के संघ ने विजयनगर के रामराय को पराजित किया\n3. चंदावर का युद्ध (1194 ई.) : मुहम्मद गौरी ने गहड़वाल शासक जयचंद्र को पराजित किया\n4. नर्मदा तट का युद्ध (पुलकेशिन II बनाम हर्ष) : चालुक्य नरेश पुलकेशिन द्वितीय ने हर्षवर्धन को हराया","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":1,"explanation":"युग्म 2 गलत है: 'खानवा का युद्ध (1527 ई.)' का सही संबंध 'बाबर ने मेवाड़ के राणा सांगा को हराकर 'गाजी' उपाधि ली' से है (न कि 'दक्कनी सल्तनतों के संघ ने विजयनगर के रामराय को पराजित किया' से)। 16 मार्च 1527 को खानवा के युद्ध में बाबर ने राणा सांगा के नेतृत्व वाले राजपूत संघ को परास्त किया।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: ऐतिहासिक युद्ध एवं परिणाम के अंतर्गत 'खानवा का युद्ध (1527 ई.)' का ऐतिहासिक संबंध 'शेर खान (शेरशाह सूरी) ने हुमायूँ को पराजित कर 'शेरशाह' उपाधि धारण की' से था।\nकथन-2: अकबर की 'दीन-ए-इलाही' (तौहीद-ए-इलाही) एक कट्टर इस्लामी सैन्य संहिता थी जिसे राजा मानसिंह और भगवानदास ने तुरंत स्वीकार किया था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'खानवा का युद्ध (1527 ई.)' का सही संबंध 'बाबर ने मेवाड़ के राणा सांगा को हराकर 'गाजी' उपाधि ली' से था — 16 मार्च 1527 को खानवा के युद्ध में बाबर ने राणा सांगा के नेतृत्व वाले राजपूत संघ को परास्त किया। (2) दीन-ए-इलाही 'सुलह-ए-कुल' (सार्वभौमिक शांति) पर आधारित नैतिक आचार संहिता थी; मानसिंह ने इसे स्वीकार करने से साफ मना कर दिया, केवल बीरबल ने इसे अपनाया।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. भक्ति आंदोलन का एकमात्र उद्देश्य संस्कृत व्याकरण के प्राचीन कर्मकांडी यज्ञों को पुनर्जीवित कर शूद्रों व महिलाओं को मठों से बाहर करना था।\n2. थॉमस रो ने जहाँगीर से अजमेर व मांडू में भेंट कर ब्रिटिश ईस्ट इंडिया कंपनी को व्यापारिक छूट दिलाई।\n3. मुगलकालीन प्रमुख युद्ध के अंतर्गत 'सामूगढ़ का युद्ध (1658 ई.)' का ऐतिहासिक संबंध 'नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला'' से था।\n4. मध्यकालीन ग्रंथ एवं लेखक के अंतर्गत 'मुन्तखब-उल-लुबाब' का ऐतिहासिक संबंध 'मिर्जा मुहम्मद (औरंगजेब काल)' से था।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":1,"explanation":"कथन 2 सत्य है (थॉमस रो ने जहाँगीर से अजमेर व मांडू में भेंट कर ब्रिटिश ईस्ट इंडिया कंपनी को व्यापारिक छूट दिलाई।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"अकबर की दहसाला व्यवस्था, मनसबदारी एवं सुलह-ए-कुल — इसके संबंध में 'प्रशासनिक व धार्मिक सुधार' कौन/क्या था?","options":["टोडरमल द्वारा 'आइन-ए-दहसाला' (1580 — 10 वर्षों का औसत); 'मनसबदारी' (मंगोल दशमलव आधारित जात व सवार रैंक); इबादतखाना (1575), महजरनामा (1579), दीन-ए-इलाही (1582)","सुलेह-ए-कुल पर आधारित मित्रता (आमेर के भारमल प्रथम राजपूत संधि 1562, भगवानदास-मानसिंह को उच्च मनसब); मेवाड़ (प्रताप), रणथंभौर, कालिंजर; 'जाट-सवार' रैंक प्रणाली","वजीर/दीवान (वित्त), मीर बख्शी (सैन्य विभाग व मनसब वेतन पत्र 'सरखत'), मीर सामां (शाही कारखाने व रसोई), काजी-उल-कुजात (न्याय)","हुमायूँ का मकबरा (दिल्ली), आगरा किला (अकबर), फतेहपुर सीकरी (बुलंद दरवाजा, पंचमहल, इबादतखाना, सलीम चिश्ती मकबरा), सिकंदरा (अकबर मकबरा — बिना गुंबद), ताजमहल"],"correct":0,"explanation":"अकबर के शासन में 'मदद-ए-माअश' (सयूरगल) भूमि विद्वानों व धार्मिक व्यक्तियों को करमुक्त अनुदान में दी जाती थी। भूमि 4 वर्गों (पोलज, परती, चाचर, बंजर) में बँटी थी।"},
  {"q":"'शाहजहाँ: स्थापत्य का स्वर्ण युग, तख्त-ए-ताऊस व उत्तराधिकार युद्ध' के ऐतिहासिक संदर्भ में 'विदेशी यात्री व पुत्र संघर्ष' निम्नलिखित में से क्या है?","options":["राजपूतों के साथ वैवाहिक-मित्रता नीति; गुजरात विजय (1572-73 — बुलंद दरवाजा, समुद्र दर्शन); असीरगढ़ (1601 — अंतिम विजय)","तुर्की भाषा में आत्मकथा 'तुजुक-ए-बाबरी' (बाबरनामा) व 'मुबइयान' पद्य शैली; चारबाग शैली की शुरुआत","बर्नियर, टैवर्नियर व मनूची का आगमन; दारा शिकोह ('सिर्र-ए-अकबर' — 52 उपनिषदों का अनुवाद) व औरंगजेब के मध्य धर्मट व सामूगढ़ (1658) युद्ध","'पट्टा व कबूलियत', 'जरीबाना' व 'मुहसिलाना' कर, सड़क-ए-आजम (ग्रैंड ट्रंक रोड) व 1700 सरायें, सासाराम (बिहार) में अष्टकोणीय मकबरा"],"correct":2,"explanation":"शाहजहाँ के काल के प्रमुख इतिहासकार अब्दुल हमीद लाहौरी ('पादशाहनामा') व इनायत खाँ ('शाहजहाँनामा') थे। सामूगढ़ व देवराई युद्ध जीतकर औरंगजेब सम्राट बना।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. वीरशैव (लिंगायत) आंदोलन   B. चौसा का युद्ध (1539 ई.)\nC. तैमूर आक्रमण (1398), सैय्यद वंश एवं लोदी राजवंश   D. फ्रांस्वा बर्नियर एवं टैवर्नियर\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["वीरशैव (लिंगायत) आंदोलन","तैमूर आक्रमण (1398), सैय्यद वंश एवं लोदी राजवंश","चौसा का युद्ध (1539 ई.)","फ्रांस्वा बर्नियर एवं टैवर्नियर"],"correct":3,"explanation":"वीरशैव (लिंगायत) आंदोलन (12वीं सदी ई.), तैमूर आक्रमण (1398), सैय्यद वंश एवं लोदी राजवंश (1504 ई.), चौसा का युद्ध (1539 ई.) (1539 ई.), फ्रांस्वा बर्नियर एवं टैवर्नियर (1658 ई.)। अतः सबसे अंत में फ्रांस्वा बर्नियर एवं टैवर्नियर।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: थॉमस रो ने जहाँगीर से अजमेर व मांडू में भेंट कर ब्रिटिश ईस्ट इंडिया कंपनी को व्यापारिक छूट दिलाई।\nकथन-2: सल्तनत काल में 'तकावी' (सोंधर) शब्द युद्ध में पराजित हिंदू राजाओं से लिए जाने वाले दंडात्मक हर्जाने के लिए प्रयुक्त होता था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (थॉमस रो ने जहाँगीर से अजमेर व मांडू में भेंट कर ब्रिटिश ईस्ट इंडिया कंपनी को व्यापारिक छूट दिलाई।)। कथन-2 गलत है — 'सोंधर' या 'तकावी' अकाल व सूखे के समय किसानों को बीज, बैल व कुओं के लिए राज्य द्वारा दिया जाने वाला अग्रिम कृषि ऋण था (मुहम्मद बिन तुगलक ने प्रमुखता से दिया)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — मध्यकालीन स्थापत्य एवं निर्माता] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. सिकंदर लोदी का मकबरा (1517) : भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन)\n2. एत्मादुद्दौला का मकबरा (आगरा) : औरंगजेब (पुत्र आजम शाह द्वारा रबिया-उद-दुर्रानी हेतु)\n3. अटाला मस्जिद (जौनपुर) : इब्राहिम शाह शर्की ('पूर्व का सिराज')\n4. गयासुद्दीन तुगलक मकबरा : ढलवाँ दीवारें ('सलामी'/Batter) व अष्टकोणीय लाल-सफेद मकबरा","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":1,"explanation":"युग्म 2 गलत है: 'एत्मादुद्दौला का मकबरा (आगरा)' का सही संबंध 'नूरजहाँ (जहाँगीर काल, 1626)' से है (न कि 'औरंगजेब (पुत्र आजम शाह द्वारा रबिया-उद-दुर्रानी हेतु)' से)। नूरजहाँ ने अपने पिता मिर्जा गियास बेग की स्मृति में यमुना तट पर एत्मादुद्दौला का मकबरा बनवाया।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. हैदराबाद राज्य (आसफजाही)   B. पानीपत का तृतीय युद्ध (1761 ई.)\nC. किताब-ए-नवरस   D. खानवा का युद्ध (1527 ई.)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["किताब-ए-नवरस","पानीपत का तृतीय युद्ध (1761 ई.)","खानवा का युद्ध (1527 ई.)","हैदराबाद राज्य (आसफजाही)"],"correct":2,"explanation":"खानवा का युद्ध (1527 ई.) (1527 ई.), किताब-ए-नवरस (1600 ई.), हैदराबाद राज्य (आसफजाही) (1724 ई.), पानीपत का तृतीय युद्ध (1761 ई.) (1761 ई.)। अतः सर्वप्रथम खानवा का युद्ध (1527 ई.)।"},
  {"q":"फ्रांसीसी चिकित्सक फ्रांस्वा बर्नियर और जौहरी टैवर्नियर मुख्यतः किस मुगल काल से जुड़े थे?","options":["शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68)","देवराय द्वितीय (विजयनगर, 1443 ई.)","देवराय प्रथम (विजयनगर, 1420 ई.)","कृष्णदेवराय (विजयनगर, ~1520 ई.)"],"correct":0,"explanation":"बर्नियर दारा शिकोह के चिकित्सक व दानिशमंद खाँ के संरक्षण में रहे तथा 12 वर्ष भारत भ्रमण किया। टैवर्नियर पेशे से हीरा-जौहरी थे जिन्होंने कोहिनूर हीरे का भी मूल्यांकन किया था।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: बर्नियर दारा शिकोह के चिकित्सक व दानिशमंद खाँ के संरक्षण में रहे तथा 12 वर्ष भारत भ्रमण किया।\nकथन-2: मनसबदारी में 'जात' पद मनसबदार के व्यक्तिगत दर्जे व वेतन को तथा 'सवार' उसके द्वारा रखे जाने वाले घुड़सवारों की संख्या को निर्धारित करता था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) बर्नियर दारा शिकोह के चिकित्सक व दानिशमंद खाँ के संरक्षण में रहे तथा 12 वर्ष भारत भ्रमण किया। (2) मनसबदारी में 'जात' पद मनसबदार के व्यक्तिगत दर्जे व वेतन को तथा 'सवार' उसके द्वारा रखे जाने वाले घुड़सवारों की संख्या को निर्धारित करता था।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 16 मार्च 1527 को खानवा के युद्ध में बाबर ने राणा सांगा के नेतृत्व वाले राजपूत संघ को परास्त किया।\nकथन-2: विजयनगर साम्राज्य पर शासन करने वाले चार राजवंशों का सही कालानुक्रम तुलुव -> संगम -> सालुव -> अराविदु था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (16 मार्च 1527 को खानवा के युद्ध में बाबर ने राणा सांगा के नेतृत्व वाले राजपूत संघ को परास्त किया।)। कथन-2 गलत है — विजयनगर पर राजवंशों का सही कालानुक्रम संगम (1336-1485) -> सालुव (1485-1505) -> तुलुव (1505-1570) -> अराविदु (1570-1650) था।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. हुमायूँनामा   B. गुरु रामदास (चौथे गुरु)\nC. जहाँगीर (सलीम): न्याय की जंजीर, चित्रकला का स्वर्ण युग व नूरजहाँ जुंटा   D. सासाराम झील मकबरा\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["सासाराम झील मकबरा","गुरु रामदास (चौथे गुरु)","हुमायूँनामा","जहाँगीर (सलीम): न्याय की जंजीर, चित्रकला का स्वर्ण युग व नूरजहाँ जुंटा"],"correct":3,"explanation":"सासाराम झील मकबरा (1545 ई.), गुरु रामदास (चौथे गुरु) (1577 ई.), हुमायूँनामा (16वीं सदी ई.), जहाँगीर (सलीम): न्याय की जंजीर, चित्रकला का स्वर्ण युग व नूरजहाँ जुंटा (1605-1627 ई.)। अतः सबसे अंत में जहाँगीर (सलीम): न्याय की जंजीर, चित्रकला का स्वर्ण युग व नूरजहाँ जुंटा।"},
  {"q":"[UPSC / CDS कालानुक्रम] निम्नलिखित ऐतिहासिक घटनाओं का प्राचीनतम से नवीनतम सही कालानुक्रम क्या है?\n1. गुरु अमरदास (तीसरे गुरु)   2. कृष्णदेवराय (तुलुव वंश) एवं अष्टदिग्गज\n3. अहमदनगर (निजामशाही, 1490)   4. मुहम्मद बिन तुगलक की पांच महत्वाकांक्षी योजनाएँ","options":["मुहम्मद बिन तुगलक की पांच महत्वाकांक्षी योजनाएँ → अहमदनगर (निजामशाही, 1490) → गुरु अमरदास (तीसरे गुरु) → कृष्णदेवराय (तुलुव वंश) एवं अष्टदिग्गज","मुहम्मद बिन तुगलक की पांच महत्वाकांक्षी योजनाएँ → अहमदनगर (निजामशाही, 1490) → कृष्णदेवराय (तुलुव वंश) एवं अष्टदिग्गज → गुरु अमरदास (तीसरे गुरु)","मुहम्मद बिन तुगलक की पांच महत्वाकांक्षी योजनाएँ → कृष्णदेवराय (तुलुव वंश) एवं अष्टदिग्गज → अहमदनगर (निजामशाही, 1490) → गुरु अमरदास (तीसरे गुरु)","अहमदनगर (निजामशाही, 1490) → मुहम्मद बिन तुगलक की पांच महत्वाकांक्षी योजनाएँ → कृष्णदेवराय (तुलुव वंश) एवं अष्टदिग्गज → गुरु अमरदास (तीसरे गुरु)"],"correct":1,"explanation":"सही कालानुक्रम: मुहम्मद बिन तुगलक की पांच महत्वाकांक्षी योजनाएँ (1325-1351 ई.), अहमदनगर (निजामशाही, 1490) (1490 ई.), कृष्णदेवराय (तुलुव वंश) एवं अष्टदिग्गज (1509-1529 ई.), गुरु अमरदास (तीसरे गुरु) (1552-1574 ई.)"},
  {"q":"शाहजहाँ: स्थापत्य का स्वर्ण युग, तख्त-ए-ताऊस व उत्तराधिकार युद्ध — इसके संबंध में 'स्थापत्य व शासन' कौन/क्या था?","options":["चौसा (1539) व कन्नौज/बिलग्राम (1540) में शेरशाह द्वारा हुमायूँ पराजित; सरहिंद युद्ध (1555 — हुमायूँ की वापसी); शेरशाह के 'रुपया' (178 ग्रेन चाँदी) व 'दाम' (ताँबा)","पानीपत II (1556 — हेमू पराजित); दास प्रथा अंत (1562), तीर्थयात्रा कर अंत (1563), जजिया अंत (1564); हल्दीघाटी (1576 — महाराणा प्रताप बनाम मानसिंह-आसफ खाँ)","ताजमहल (उस्ताद अहमद लाहौरी), दिल्ली लाल किला (शाहजहाँनाबाद), जामा मस्जिद, मोती मस्जिद (आगरा) व मयूर सिंहासन (बेबादल खाँ); मनसबदारी में 'माहवार' वेतन","पानीपत I (1526 — इब्राहिम लोदी, तुलुगमा व उस्ताद अली/मुस्तफा तोपखाना); खानवा (1527 — राणा सांगा, जिहाद व तमगा समाप्ति); चंदेरी (1528 — मेदिनीराय); घाघरा (1529 — महमूद लोदी)"],"correct":2,"explanation":"शाहजहाँ के काल के प्रमुख इतिहासकार अब्दुल हमीद लाहौरी ('पादशाहनामा') व इनायत खाँ ('शाहजहाँनामा') थे। सामूगढ़ व देवराई युद्ध जीतकर औरंगजेब सम्राट बना।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. मध्यकालीन ग्रंथ एवं लेखक के अंतर्गत 'मुन्तखब-उल-लुबाब' का ऐतिहासिक संबंध 'मिर्जा मुहम्मद (औरंगजेब काल)' से था।\n2. मई 1658 में आगरा के निकट सामूगढ़ युद्ध में औरंगजेब की जीत से शाहजहाँ कैद व उत्तराधिकार तय हुआ।\n3. सल्तनत विभाग एवं सुल्तान के अंतर्गत 'दीवान-ए-खैरात' का ऐतिहासिक संबंध 'शाही पत्राचार, फरमान व अभिलेख विभाग' से था।\n4. पानीपत के तृतीय युद्ध (1761) में पेशवा बाजीराव प्रथम ने स्वयं मराठा सेना का नेतृत्व कर अहमद शाह अब्दाली को परास्त किया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":1,"explanation":"कथन 2 सत्य है (मई 1658 में आगरा के निकट सामूगढ़ युद्ध में औरंगजेब की जीत से शाहजहाँ कैद व उत्तराधिकार तय हुआ।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. सुल्तान नासिरुद्दीन महमूद के काल में मुख्य काजी मिनहाज-उस-सिराज ने फारसी में यह ग्रंथ लिखा।\n2. गुरु अर्जुन देव की शहादत के बाद छठे गुरु हरगोबिंद ने सिखों का सैन्यीकरण किया और अमृतसर की किलेबंदी की।\n3. सर थॉमस रो जेम्स प्रथम के राजदूत के रूप में मुगल बादशाह शाहजहाँ के दरबार में सूरत से पूर्व बंगाल विजय के समय आए थे।\n4. 17 मार्च 1527 को खानवा में बाबर ने जिहाद का नारा देकर राणा सांगा के राजपूत संघ को हराया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: सर थॉमस रो (1615-1619) ब्रिटेन के राजा जेम्स I के दूत के रूप में जहाँगीर के दरबार में (अजमेर/मांडू) आए और व्यापारिक फरमान प्राप्त किया।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. बहमनी सल्तनत के विघटन के बाद गोलकुंडा के कुतुबशाही सुल्तान मुहम्मद कुली कुतुब शाह ने हैदराबाद नगर तथा चारमीनार (1591) का निर्माण कराया।\n2. 1556 ई. में बैरम खाँ के संरक्षण में अकबर ने पानीपत के द्वितीय युद्ध में आदिल शाह सूर के हिंदू सेनापति हेमू ('विक्रमादित्य') को हराकर मुगल सत्ता पुनः स्थापित की।\n3. दारा शिकोह ने समूचे सिख 'आदि ग्रंथ' का तुर्की भाषा में 'मज्म-उल-बहरीन' नाम से अनुवाद कर औरंगजेब को भेंट किया।\n4. मलिक अहमद ने 1490 में अहमदनगर की स्थापना की; यहीं वजीर मलिक अंबर ने छापामार युद्ध व राजस्व सुधार किए।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: दारा शिकोह ने फारसी भाषा में 52 उपनिषदों का अनुवाद 'सिर्र-ए-अकबर' (महान रहस्य) नाम से तथा स्वतंत्र तुलनात्मक ग्रंथ 'मज्म-उल-बहरीन' (दो समुद्रों का संगम) लिखा।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: भक्ति आंदोलन का एकमात्र उद्देश्य संस्कृत व्याकरण के प्राचीन कर्मकांडी यज्ञों को पुनर्जीवित कर शूद्रों व महिलाओं को मठों से बाहर करना था।\nकथन-2: मुहम्मद बिन तुगलक ने दोआब में खेती सुधारने हेतु 'दीवान-ए-अमीर कोही' बनाया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है (भक्ति आंदोलन ने सरल प्रेम व समर्पण द्वारा कर्मकांडीय जटिलता का विरोध किया और निम्न जातियों व महिलाओं को समान आध्यात्मिक अधिकार दिया।)। कथन-2 सत्य है (मुहम्मद बिन तुगलक ने दोआब में खेती सुधारने हेतु 'दीवान-ए-अमीर कोही' बनाया।)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 18 जून 1576 को अरावली की हल्दीघाटी में मेवाड़ के महाराणा प्रताप ने अदम्य शौर्य दिखाया।\nकथन-2: मुगल प्रशासन में 'मीर बख्शी' साम्राज्य का मुख्य सेनापति (कमांडर-इन-चीफ) होता था और सम्राट के बिना भी युद्ध की घोषणा कर सकता था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (18 जून 1576 को अरावली की हल्दीघाटी में मेवाड़ के महाराणा प्रताप ने अदम्य शौर्य दिखाया।)। कथन-2 गलत है — मीर बख्शी सैन्य प्रशासनिक प्रमुख था (भर्ती, दाग-चेहरा, वेतन बिल सत्यापन), किंतु वह प्रधान सेनापति नहीं था—मुख्य कमान सम्राट या नियुक्त सिपहसालार के हाथ होती थी।"},
  {"q":"1539 ई. के 'चौसा के युद्ध' में हुमायूँ को किस अफगान शासक से पराजय मिली?","options":["चालुक्य नरेश पुलकेशिन द्वितीय ने हर्षवर्धन को हराया","सिकंदर ने पंजाब के शासक पोरस को पराजित कर मैत्री की","राजा सुदास (भरत जन) ने दस राजाओं के संघ को पराजित किया","शेर खान (शेरशाह सूरी) ने हुमायूँ को पराजित कर 'शेरशाह' उपाधि धारण की"],"correct":3,"explanation":"1539 ई. में बक्सर के निकट चौसा के युद्ध में शेरशाह सूरी ने हुमायूँ को पराजित किया। डूबते हुमायूँ की जान निजाम नामक भिश्ती ने बचाई, जिसे उसने एक दिन का बादशाह बनाया।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक युद्ध एवं परिणाम] निम्नलिखित युग्मों पर विचार कीजिए:\n1. खानवा का युद्ध (1527 ई.) : राष्ट्रकूट कृष्ण तृतीय ने चोल शासक परांतक प्रथम के पुत्र राजादित्य को हराया\n2. तक्कोलम का युद्ध (949 ई.) : चालुक्य नरेश पुलकेशिन द्वितीय ने हर्षवर्धन को हराया\n3. नर्मदा तट का युद्ध (पुलकेशिन II बनाम हर्ष) : सिकंदर ने पंजाब के शासक पोरस को पराजित कर मैत्री की\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: खानवा का युद्ध (1527 ई.) — बाबर ने मेवाड़ के राणा सांगा को हराकर 'गाजी' उपाधि ली)। युग्म 2 गलत (सही: तक्कोलम का युद्ध (949 ई.) — राष्ट्रकूट कृष्ण तृतीय ने चोल शासक परांतक प्रथम के पुत्र राजादित्य को हराया)। युग्म 3 गलत (सही: नर्मदा तट का युद्ध (पुलकेशिन II बनाम हर्ष) — चालुक्य नरेश पुलकेशिन द्वितीय ने हर्षवर्धन को हराया)।"},
  {"q":"[UPSC Prelims पैटर्न — मध्यकालीन स्थापत्य एवं निर्माता] निम्नलिखित युग्मों पर विचार कीजिए:\n1. एत्मादुद्दौला का मकबरा (आगरा) : नूरजहाँ (जहाँगीर काल, 1626)\n2. बीबी का मकबरा (औरंगाबाद) : भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन)\n3. सिकंदर लोदी का मकबरा (1517) : ढलवाँ दीवारें ('सलामी'/Batter) व अष्टकोणीय लाल-सफेद मकबरा\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (नूरजहाँ ने अपने पिता मिर्जा गियास बेग की स्मृति में यमुना तट पर एत्मादुद्दौला का मकबरा बनवाया।) युग्म 2 गलत (सही: बीबी का मकबरा (औरंगाबाद) — औरंगजेब (पुत्र आजम शाह द्वारा रबिया-उद-दुर्रानी हेतु))। युग्म 3 गलत (सही: सिकंदर लोदी का मकबरा (1517) — भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — ऐतिहासिक युद्ध एवं परिणाम] सूची-I को सूची-II से सुमेलित कीजिए:\nA. खानवा का युद्ध (1527 ई.)   |   1. सिकंदर ने पंजाब के शासक पोरस को पराजित कर मैत्री की\nB. दाशराज्ञ युद्ध (परुष्णी नदी)   |   2. राष्ट्रकूट कृष्ण तृतीय ने चोल शासक परांतक प्रथम के पुत्र राजादित्य को हराया\nC. तक्कोलम का युद्ध (949 ई.)   |   3. बाबर ने मेवाड़ के राणा सांगा को हराकर 'गाजी' उपाधि ली\nD. हाइडेस्पीज का युद्ध (326 ई.पू.)   |   4. राजा सुदास (भरत जन) ने दस राजाओं के संघ को पराजित किया","options":["A-3, B-4, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-3, C-2, D-1","A-3, B-2, C-4, D-1"],"correct":1,"explanation":"सही सुमेलन: खानवा का युद्ध (1527 ई.) (बाबर ने मेवाड़ के राणा सांगा को हराकर 'गाजी' उपाधि ली), दाशराज्ञ युद्ध (परुष्णी नदी) (राजा सुदास (भरत जन) ने दस राजाओं के संघ को पराजित किया), तक्कोलम का युद्ध (949 ई.) (राष्ट्रकूट कृष्ण तृतीय ने चोल शासक परांतक प्रथम के पुत्र राजादित्य को हराया), हाइडेस्पीज का युद्ध (326 ई.पू.) (सिकंदर ने पंजाब के शासक पोरस को पराजित कर मैत्री की)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. मुगलकालीन प्रशासनिक शब्दावली के अंतर्गत 'परती (Parauti)' का ऐतिहासिक संबंध 'विद्वानों, संतों व धार्मिक संस्थानों को करमुक्त अनुदान भूमि' से था।\n2. मनसबदारी में 'जात' पद मनसबदार के व्यक्तिगत दर्जे व वेतन को तथा 'सवार' उसके द्वारा रखे जाने वाले घुड़सवारों की संख्या को निर्धारित करता था।\n3. कुतुबुद्दीन ऐबक ने दिल्ली को अपनी स्थायी राजधानी बनाया और बगदाद के खलीफा से सुल्तान की औपचारिक उपाधि व सनद प्राप्त की।\n4. कादिरी सूफी सिलसिला संगीत का कट्टर विरोधी था और इसने दारा शिकोह को सूफी रहस्यवाद की शिक्षा देने से मना कर दिया था।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":1,"explanation":"कथन 2 सत्य है (मनसबदारी में 'जात' पद मनसबदार के व्यक्तिगत दर्जे व वेतन को तथा 'सवार' उसके द्वारा रखे जाने वाले घुड़सवारों की संख्या को निर्धारित करता था।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[PSC/CDS युग्म पहचान — मुगलकालीन प्रमुख युद्ध] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. चौसा का युद्ध (1539 ई.) : बाबर बनाम राणा सांगा (मेवाड़)\n2. सामूगढ़ का युद्ध (1658 ई.) : औरंगजेब व मुराद बनाम दारा शिकोह\n3. खानवा युद्ध (1527 ई.) : महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ)\n4. हल्दीघाटी युद्ध (1576 ई.) : नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला'","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: मई 1658 में आगरा के निकट सामूगढ़ युद्ध में औरंगजेब की जीत से शाहजहाँ कैद व उत्तराधिकार तय हुआ। (अन्य सही युग्म: चौसा का युद्ध (1539 ई.)→शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय, खानवा युद्ध (1527 ई.)→बाबर बनाम राणा सांगा (मेवाड़), हल्दीघाटी युद्ध (1576 ई.)→महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ))।"},
  {"q":"[UPSC Prelims पैटर्न — मध्यकालीन स्थापत्य एवं निर्माता] निम्नलिखित युग्मों पर विचार कीजिए:\n1. एत्मादुद्दौला का मकबरा (आगरा) : भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन)\n2. सिकंदर लोदी का मकबरा (1517) : शेरशाह सूरी\n3. सासाराम झील मकबरा : ढलवाँ दीवारें ('सलामी'/Batter) व अष्टकोणीय लाल-सफेद मकबरा\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: एत्मादुद्दौला का मकबरा (आगरा) — नूरजहाँ (जहाँगीर काल, 1626))। युग्म 2 गलत (सही: सिकंदर लोदी का मकबरा (1517) — भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन))। युग्म 3 गलत (सही: सासाराम झील मकबरा — शेरशाह सूरी)।"},
  {"q":"ऐतिहासिक संदर्भ में ''जंजीर-ए-अदल' (यमुना तट तक); गुरु अर्जुन देव को मृत्युदंड (खुसरो सहायता पर); कैप्टन विलियम हॉकिन्स (1608) व सर थॉमस रो (1615) का आगमन; दु-अस्पा सिह-अस्पा प्रथा' (शासन व विदेश संपर्क) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["जहाँगीर (सलीम): न्याय की जंजीर, चित्रकला का स्वर्ण युग व नूरजहाँ जुंटा","हुमायूँ एवं शेरशाह सूरी (प्रशासन व आर्थिक सुधार)","अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान","बाबर की भारत विजय व चार प्रमुख युद्ध (1526–1529)"],"correct":0,"explanation":"जहाँगीर की आत्मकथा 'तुजुक-ए-जहाँगीरी' फारसी में है (जिसे मोतमिद खाँ ने पूरा किया)। उसने कंधार खोया, किंतु मेवाड़ (अमर सिंह से सम्मानजनक संधि 1615) व कांगड़ा जीते।"},
  {"q":"'जहाँगीर (सलीम): न्याय की जंजीर, चित्रकला का स्वर्ण युग व नूरजहाँ जुंटा' के ऐतिहासिक संदर्भ में 'स्थापत्य व कला' निम्नलिखित में से क्या है?","options":["राजपूतों के साथ वैवाहिक-मित्रता नीति; गुजरात विजय (1572-73 — बुलंद दरवाजा, समुद्र दर्शन); असीरगढ़ (1601 — अंतिम विजय)","तुर्की भाषा में आत्मकथा 'तुजुक-ए-बाबरी' (बाबरनामा) व 'मुबइयान' पद्य शैली; चारबाग शैली की शुरुआत","नूरजहाँ द्वारा पित्रादुरा (Pietra Dura) युक्त एत्मादुद्दौला मकबरा (पूर्णतः संगमरमर की प्रथम मुगल इमारत); उस्ताद मंसूर (पक्षी) व अबुल हसन चित्रकार","'पट्टा व कबूलियत', 'जरीबाना' व 'मुहसिलाना' कर, सड़क-ए-आजम (ग्रैंड ट्रंक रोड) व 1700 सरायें, सासाराम (बिहार) में अष्टकोणीय मकबरा"],"correct":2,"explanation":"जहाँगीर की आत्मकथा 'तुजुक-ए-जहाँगीरी' फारसी में है (जिसे मोतमिद खाँ ने पूरा किया)। उसने कंधार खोया, किंतु मेवाड़ (अमर सिंह से सम्मानजनक संधि 1615) व कांगड़ा जीते।"},
  {"q":"[PSC/CDS युग्म पहचान — विदेशी यात्री एवं शासक] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. सर थॉमस रो (ब्रिटेन) : जहाँगीर (1615-1619 ई.)\n2. निकोलो कोंटी (इटली) : बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)\n3. अफनासी निकितिन (रूस) : कृष्णदेवराय (विजयनगर, ~1520 ई.)\n4. डोमिंगो पायस (पुर्तगाल) : देवराय द्वितीय (विजयनगर, 1443 ई.)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: थॉमस रो ने जहाँगीर से अजमेर व मांडू में भेंट कर ब्रिटिश ईस्ट इंडिया कंपनी को व्यापारिक छूट दिलाई। (अन्य सही युग्म: निकोलो कोंटी (इटली)→देवराय प्रथम (विजयनगर, 1420 ई.), अफनासी निकितिन (रूस)→बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.), डोमिंगो पायस (पुर्तगाल)→कृष्णदेवराय (विजयनगर, ~1520 ई.))।"},
  {"q":"जहाँगीर (सलीम): न्याय की जंजीर, चित्रकला का स्वर्ण युग व नूरजहाँ जुंटा — इसके संबंध में 'शासन व विदेश संपर्क' कौन/क्या था?","options":["पानीपत II (1556 — हेमू पराजित); दास प्रथा अंत (1562), तीर्थयात्रा कर अंत (1563), जजिया अंत (1564); हल्दीघाटी (1576 — महाराणा प्रताप बनाम मानसिंह-आसफ खाँ)","चौसा (1539) व कन्नौज/बिलग्राम (1540) में शेरशाह द्वारा हुमायूँ पराजित; सरहिंद युद्ध (1555 — हुमायूँ की वापसी); शेरशाह के 'रुपया' (178 ग्रेन चाँदी) व 'दाम' (ताँबा)","पानीपत I (1526 — इब्राहिम लोदी, तुलुगमा व उस्ताद अली/मुस्तफा तोपखाना); खानवा (1527 — राणा सांगा, जिहाद व तमगा समाप्ति); चंदेरी (1528 — मेदिनीराय); घाघरा (1529 — महमूद लोदी)","'जंजीर-ए-अदल' (यमुना तट तक); गुरु अर्जुन देव को मृत्युदंड (खुसरो सहायता पर); कैप्टन विलियम हॉकिन्स (1608) व सर थॉमस रो (1615) का आगमन; दु-अस्पा सिह-अस्पा प्रथा"],"correct":3,"explanation":"जहाँगीर की आत्मकथा 'तुजुक-ए-जहाँगीरी' फारसी में है (जिसे मोतमिद खाँ ने पूरा किया)। उसने कंधार खोया, किंतु मेवाड़ (अमर सिंह से सम्मानजनक संधि 1615) व कांगड़ा जीते।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: भक्ति मत एवं प्रवर्तक के अंतर्गत 'वीरशैव (लिंगायत) आंदोलन' का ऐतिहासिक संबंध 'श्रीमंत शंकरदेव' से था।\nकथन-2: मुहम्मद बिन तुगलक ने दोआब में खेती सुधारने हेतु 'दीवान-ए-अमीर कोही' बनाया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है ('वीरशैव (लिंगायत) आंदोलन' का सही संबंध 'बसवन्ना (बसव)' से था — कल्चुरी राजा बिज्जल के मंत्री बसवन्ना ने जातिभेद व वैदिक कर्मकांड के विरुद्ध वीरशैव परंपरा शुरू की।)। कथन-2 सत्य है (मुहम्मद बिन तुगलक ने दोआब में खेती सुधारने हेतु 'दीवान-ए-अमीर कोही' बनाया।)।"},
  {"q":"ऐतिहासिक संदर्भ में 'ताजमहल (उस्ताद अहमद लाहौरी), दिल्ली लाल किला (शाहजहाँनाबाद), जामा मस्जिद, मोती मस्जिद (आगरा) व मयूर सिंहासन (बेबादल खाँ); मनसबदारी में 'माहवार' वेतन' (स्थापत्य व शासन) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["हुमायूँ एवं शेरशाह सूरी (प्रशासन व आर्थिक सुधार)","बाबर की भारत विजय व चार प्रमुख युद्ध (1526–1529)","शाहजहाँ: स्थापत्य का स्वर्ण युग, तख्त-ए-ताऊस व उत्तराधिकार युद्ध","अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान"],"correct":2,"explanation":"शाहजहाँ के काल के प्रमुख इतिहासकार अब्दुल हमीद लाहौरी ('पादशाहनामा') व इनायत खाँ ('शाहजहाँनामा') थे। सामूगढ़ व देवराई युद्ध जीतकर औरंगजेब सम्राट बना।"},
  {"q":"[PSC/CDS युग्म पहचान — विदेशी यात्री एवं शासक] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. अब्दुर रज्जाक (फारस/समरकंद) : बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)\n2. फ्रांस्वा बर्नियर एवं टैवर्नियर : शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68)\n3. अफनासी निकितिन (रूस) : अच्युतदेवराय (विजयनगर, ~1535 ई.)\n4. फर्नओ नूनिज (पुर्तगाल) : जहाँगीर (1615-1619 ई.)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: बर्नियर दारा शिकोह के चिकित्सक व दानिशमंद खाँ के संरक्षण में रहे तथा 12 वर्ष भारत भ्रमण किया। (अन्य सही युग्म: अब्दुर रज्जाक (फारस/समरकंद)→देवराय द्वितीय (विजयनगर, 1443 ई.), अफनासी निकितिन (रूस)→बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.), फर्नओ नूनिज (पुर्तगाल)→अच्युतदेवराय (विजयनगर, ~1535 ई.))।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: सर थॉमस रो जेम्स प्रथम के राजदूत के रूप में मुगल बादशाह शाहजहाँ के दरबार में सूरत से पूर्व बंगाल विजय के समय आए थे।\nकथन-2: मुहम्मद बिन तुगलक ने इब्नबतूता को दिल्ली का काजी नियुक्त किया और 1342 में चीन राजदूत भेजा।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है (सर थॉमस रो (1615-1619) ब्रिटेन के राजा जेम्स I के दूत के रूप में जहाँगीर के दरबार में (अजमेर/मांडू) आए और व्यापारिक फरमान प्राप्त किया।)। कथन-2 सत्य है (मुहम्मद बिन तुगलक ने इब्नबतूता को दिल्ली का काजी नियुक्त किया और 1342 में चीन राजदूत भेजा।)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — विदेशी यात्री एवं शासक] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. डोमिंगो पायस (पुर्तगाल) : कृष्णदेवराय (विजयनगर, ~1520 ई.)\n2. अफनासी निकितिन (रूस) : बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)\n3. सर थॉमस रो (ब्रिटेन) : देवराय द्वितीय (विजयनगर, 1443 ई.)\n4. निकोलो कोंटी (इटली) : देवराय प्रथम (विजयनगर, 1420 ई.)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'सर थॉमस रो (ब्रिटेन)' का सही संबंध 'जहाँगीर (1615-1619 ई.)' से है (न कि 'देवराय द्वितीय (विजयनगर, 1443 ई.)' से)। थॉमस रो ने जहाँगीर से अजमेर व मांडू में भेंट कर ब्रिटिश ईस्ट इंडिया कंपनी को व्यापारिक छूट दिलाई।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. एत्मादुद्दौला का मकबरा (आगरा)   B. गुरु हरगोबिंद (छठे गुरु)\nC. किताब-ए-नवरस   D. सासाराम झील मकबरा\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["किताब-ए-नवरस","सासाराम झील मकबरा","गुरु हरगोबिंद (छठे गुरु)","एत्मादुद्दौला का मकबरा (आगरा)"],"correct":3,"explanation":"सासाराम झील मकबरा (1545 ई.), किताब-ए-नवरस (1600 ई.), गुरु हरगोबिंद (छठे गुरु) (1606-1644 ई.), एत्मादुद्दौला का मकबरा (आगरा) (1626 ई.)। अतः सबसे अंत में एत्मादुद्दौला का मकबरा (आगरा)।"},
  {"q":"[UPSC / CDS कालानुक्रम] निम्नलिखित ऐतिहासिक घटनाओं का प्राचीनतम से नवीनतम सही कालानुक्रम क्या है?\n1. पानीपत का तृतीय युद्ध (1761 ई.)   2. औरंगजेब (आलमगीर): नीतियाँ, दक्कन अभियान व विद्रोह\n3. शुद्धाद्वैतवाद एवं पुष्टिमार्ग   4. पुरंदर की संधि (1665 ई.)","options":["शुद्धाद्वैतवाद एवं पुष्टिमार्ग → पुरंदर की संधि (1665 ई.) → औरंगजेब (आलमगीर): नीतियाँ, दक्कन अभियान व विद्रोह → पानीपत का तृतीय युद्ध (1761 ई.)","पुरंदर की संधि (1665 ई.) → शुद्धाद्वैतवाद एवं पुष्टिमार्ग → औरंगजेब (आलमगीर): नीतियाँ, दक्कन अभियान व विद्रोह → पानीपत का तृतीय युद्ध (1761 ई.)","शुद्धाद्वैतवाद एवं पुष्टिमार्ग → औरंगजेब (आलमगीर): नीतियाँ, दक्कन अभियान व विद्रोह → पुरंदर की संधि (1665 ई.) → पानीपत का तृतीय युद्ध (1761 ई.)","शुद्धाद्वैतवाद एवं पुष्टिमार्ग → पुरंदर की संधि (1665 ई.) → पानीपत का तृतीय युद्ध (1761 ई.) → औरंगजेब (आलमगीर): नीतियाँ, दक्कन अभियान व विद्रोह"],"correct":0,"explanation":"सही कालानुक्रम: शुद्धाद्वैतवाद एवं पुष्टिमार्ग (15वीं-16वीं सदी), पुरंदर की संधि (1665 ई.) (1665 ई.), औरंगजेब (आलमगीर): नीतियाँ, दक्कन अभियान व विद्रोह (1658-1707 ई.), पानीपत का तृतीय युद्ध (1761 ई.) (1761 ई.)"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. गुरु अमरदास ने सती व पर्दा प्रथा का विरोध किया तथा सम्राट अकबर से गोइंदवाल में भेंट की।\n2. 1192 ई. का तराइन का द्वितीय युद्ध भारतीय इतिहास का युगांतकारी मोड़ था जिसने उत्तर भारत में चौहान शक्ति को समाप्त कर मुस्लिम तुर्क सत्ता स्थापित की।\n3. मुगलकालीन प्रमुख युद्ध के अंतर्गत 'सामूगढ़ का युद्ध (1658 ई.)' का ऐतिहासिक संबंध 'नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला'' से था।\n4. निम्बार्काचार्य ने सनकादि संप्रदाय की स्थापना कर राधा-कृष्ण भक्ति को लोकप्रिय बनाया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: 'सामूगढ़ का युद्ध (1658 ई.)' का सही संबंध 'औरंगजेब व मुराद बनाम दारा शिकोह' से था — मई 1658 में आगरा के निकट सामूगढ़ युद्ध में औरंगजेब की जीत से शाहजहाँ कैद व उत्तराधिकार तय हुआ।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. मुगलकालीन प्रमुख युद्ध के अंतर्गत 'हल्दीघाटी युद्ध (1576 ई.)' का ऐतिहासिक संबंध 'औरंगजेब व मुराद बनाम दारा शिकोह' से था।\n2. शाहजहाँ ने बलख-बदख्शां का मध्य एशिया अभियान किया, पुर्तगालियों को 1632 में हुगली से खदेड़ा और अहमदनगर (1633) को पूरी तरह मुगल साम्राज्य में मिलाया।\n3. ऐतिहासिक युद्ध एवं परिणाम के अंतर्गत 'चौसा का युद्ध (1539 ई.)' का ऐतिहासिक संबंध 'अकबर-बैरम खाँ ने आदिल शाह के सेनापति हेमू (विक्रमादित्य) को हराया' से था।\n4. क्षेत्रीय राज्य एवं संस्थापक के अंतर्गत 'हैदराबाद राज्य (आसफजाही)' का ऐतिहासिक संबंध 'सआदत खाँ 'बुरहान-उल-मुल्क'' से था।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":1,"explanation":"कथन 2 सत्य है (शाहजहाँ ने बलख-बदख्शां का मध्य एशिया अभियान किया, पुर्तगालियों को 1632 में हुगली से खदेड़ा और अहमदनगर (1633) को पूरी तरह मुगल साम्राज्य में मिलाया।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. मध्यकालीन स्थापत्य एवं निर्माता के अंतर्गत 'एत्मादुद्दौला का मकबरा (आगरा)' का ऐतिहासिक संबंध 'औरंगजेब (पुत्र आजम शाह द्वारा रबिया-उद-दुर्रानी हेतु)' से था।\n2. चिश्तियों के विपरीत शेख बहाउद्दीन जकरिया ने सुल्तान इल्तुतमिश से 'शेख-उल-इस्लाम' पद व धन स्वीकार किया।\n3. रामानंद ने भक्ति के द्वार सभी जातियों व स्त्रियों के लिए खोले; उनके शिष्यों में कबीर (जुलाहा), रैदास (चर्मकार), धन्ना (जाट), सेन (नाई) व पीपा शामिल थे।\n4. तक्कोलम के युद्ध में राष्ट्रकूट राजा कृष्ण तृतीय ने चोलों को करारी हार दी।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":0,"explanation":"कथन 1 असत्य है। सुधार: 'एत्मादुद्दौला का मकबरा (आगरा)' का सही संबंध 'नूरजहाँ (जहाँगीर काल, 1626)' से था — नूरजहाँ ने अपने पिता मिर्जा गियास बेग की स्मृति में यमुना तट पर एत्मादुद्दौला का मकबरा बनवाया।"},
  {"q":"मुगल वास्तुकला में पूर्णतः सफेद संगमरमर व 'पित्रादुरा' (रत्न जड़ाई) का प्रथम भव्य प्रयोग किस इमारत में हुआ?","options":["अलाउद्दीन खिलजी","ढलवाँ दीवारें ('सलामी'/Batter) व अष्टकोणीय लाल-सफेद मकबरा","भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन)","नूरजहाँ (जहाँगीर काल, 1626)"],"correct":3,"explanation":"नूरजहाँ ने अपने पिता मिर्जा गियास बेग की स्मृति में यमुना तट पर एत्मादुद्दौला का मकबरा बनवाया। पर्सी ब्राउन ने इसे 'ताजमहल का पूर्वगामी' व संगमरमर काल का प्रारंभ कहा।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: मध्यकालीन ग्रंथ एवं लेखक के अंतर्गत 'फतवा-ए-जहाँदारी' का ऐतिहासिक संबंध 'कृष्णदेवराय' से था।\nकथन-2: मराठा अष्टप्रधान परिषद के अंतर्गत 'सुमंत (दबीर)' का ऐतिहासिक संबंध 'वित्त एवं राजस्व लेखा-जोखा मंत्री' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'फतवा-ए-जहाँदारी' का सही संबंध 'जियाउद्दीन बरनी' से था — बरनी ने बलबन से फिरोजशाह तुगलक के प्रारंभिक काल तक का राजनीतिक इतिहास व राजत्व सिद्धांत लिखा। (2) 'सुमंत (दबीर)' का सही संबंध 'विदेश मंत्री (अंतर-राज्यीय संबंध)' से था — अष्टप्रधान में सुमंत/दबीर अन्य राज्यों से संधि व विदेश मामले संभालते थे।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: मनसबदारी में 'जात' पद मनसबदार के व्यक्तिगत दर्जे व वेतन को तथा 'सवार' उसके द्वारा रखे जाने वाले घुड़सवारों की संख्या को निर्धारित करता था।\nकथन-2: मध्यकालीन स्थापत्य एवं निर्माता के अंतर्गत 'एत्मादुद्दौला का मकबरा (आगरा)' का ऐतिहासिक संबंध 'औरंगजेब (पुत्र आजम शाह द्वारा रबिया-उद-दुर्रानी हेतु)' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (मनसबदारी में 'जात' पद मनसबदार के व्यक्तिगत दर्जे व वेतन को तथा 'सवार' उसके द्वारा रखे जाने वाले घुड़सवारों की संख्या को निर्धारित करता था।)। कथन-2 गलत है — 'एत्मादुद्दौला का मकबरा (आगरा)' का सही संबंध 'नूरजहाँ (जहाँगीर काल, 1626)' से था — नूरजहाँ ने अपने पिता मिर्जा गियास बेग की स्मृति में यमुना तट पर एत्मादुद्दौला का मकबरा बनवाया।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 1539 ई. में बक्सर के निकट चौसा के युद्ध में शेरशाह सूरी ने हुमायूँ को पराजित किया।\nकथन-2: शंकरदेव ने मूर्तिपूजा व बलि का विरोध कर 'नामघर' व 'सत्र' मठों की स्थापना की।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) 1539 ई. में बक्सर के निकट चौसा के युद्ध में शेरशाह सूरी ने हुमायूँ को पराजित किया। (2) शंकरदेव ने मूर्तिपूजा व बलि का विरोध कर 'नामघर' व 'सत्र' मठों की स्थापना की।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. इक्ता प्रणाली (इल्तुतमिश द्वारा सुसंगठित) के अंतर्गत भूमि का हस्तांतरणीय राजस्व आवंटन सैन्य-नागरिक अधिकारियों (इक्तादार/मुक्ता/वली) को वेतन के बदले किया जाता था।\n2. अकबर ने फतेहपुर सीकरी में 'मकतबखाना' (अनुवाद विभाग) स्थापित कराया जहाँ संस्कृत के प्रमुख महाकाव्यों व विज्ञान ग्रंथों का फारसी में अनुवाद हुआ।\n3. सिकंदरा (आगरा) में स्थित सम्राट अकबर का मकबरा अपने विशाल सुनहरे प्याजनुमा गुंबद व पूर्णतः हिंदू शिखर शैली के अभाव के लिए प्रसिद्ध है।\n4. मिर्जा मुहम्मद ने औरंगजेब के काल में भारतीय संगीत, छंद व रागों के परिचय हेतु यह फारसी ग्रंथ लिखा।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: अकबर के मकबरे (सिकंदरा) की सबसे अनोखी विशेषता यह है कि वह पंचमंजिला पिरामिडनुमा है और उसमें कोई गुंबद (Domeless) नहीं है।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. मध्यकालीन ग्रंथ एवं लेखक के अंतर्गत 'आमुक्तमाल्यद' का ऐतिहासिक संबंध 'गुलबदन बेगम' से था।\n2. विदेशी यात्री एवं शासक के अंतर्गत 'फर्नओ नूनिज (पुर्तगाल)' का ऐतिहासिक संबंध 'बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)' से था।\n3. आलू, तंबाकू और मक्का ऋग्वैदिक काल से ही भारत की प्राचीनतम मुख्य फसलें थीं जिनका वर्णन चरक संहिता में विस्तार से है।\n4. 16 मार्च 1527 को खानवा के युद्ध में बाबर ने राणा सांगा के नेतृत्व वाले राजपूत संघ को परास्त किया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (16 मार्च 1527 को खानवा के युद्ध में बाबर ने राणा सांगा के नेतृत्व वाले राजपूत संघ को परास्त किया।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[PSC/CDS युग्म पहचान — मध्यकालीन स्थापत्य एवं निर्माता] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. सिकंदर लोदी का मकबरा (1517) : औरंगजेब (पुत्र आजम शाह द्वारा रबिया-उद-दुर्रानी हेतु)\n2. बीबी का मकबरा (औरंगाबाद) : अलाउद्दीन खिलजी\n3. एत्मादुद्दौला का मकबरा (आगरा) : नूरजहाँ (जहाँगीर काल, 1626)\n4. अलाई दरवाजा (1311 ई.) : ढलवाँ दीवारें ('सलामी'/Batter) व अष्टकोणीय लाल-सफेद मकबरा","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: नूरजहाँ ने अपने पिता मिर्जा गियास बेग की स्मृति में यमुना तट पर एत्मादुद्दौला का मकबरा बनवाया। (अन्य सही युग्म: सिकंदर लोदी का मकबरा (1517)→भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन), बीबी का मकबरा (औरंगाबाद)→औरंगजेब (पुत्र आजम शाह द्वारा रबिया-उद-दुर्रानी हेतु), अलाई दरवाजा (1311 ई.)→अलाउद्दीन खिलजी)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — ऐतिहासिक युद्ध एवं परिणाम] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. पानीपत का द्वितीय युद्ध (1556 ई.) : अकबर-बैरम खाँ ने आदिल शाह के सेनापति हेमू (विक्रमादित्य) को हराया\n2. तालीकोटा का युद्ध (1565 ई.) : दक्कनी सल्तनतों के संघ ने विजयनगर के रामराय को पराजित किया\n3. तराइन का प्रथम युद्ध (1191 ई.) : पृथ्वीराज चौहान तृतीय ने मुहम्मद गौरी को पराजित किया\n4. चौसा का युद्ध (1539 ई.) : अहमद शाह अब्दाली ने सदाशिवराव भाऊ के नेतृत्व वाली मराठा सेना को हराया","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":3,"explanation":"युग्म 4 गलत है: 'चौसा का युद्ध (1539 ई.)' का सही संबंध 'शेर खान (शेरशाह सूरी) ने हुमायूँ को पराजित कर 'शेरशाह' उपाधि धारण की' से है (न कि 'अहमद शाह अब्दाली ने सदाशिवराव भाऊ के नेतृत्व वाली मराठा सेना को हराया' से)। 1539 ई. में बक्सर के निकट चौसा के युद्ध में शेरशाह सूरी ने हुमायूँ को पराजित किया।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. विदेशी यात्री एवं शासक के अंतर्गत 'फ्रांस्वा बर्नियर एवं टैवर्नियर' का ऐतिहासिक संबंध 'देवराय प्रथम (विजयनगर, 1420 ई.)' से था।\n2. 16 मार्च 1527 को खानवा के युद्ध में बाबर ने राणा सांगा के नेतृत्व वाले राजपूत संघ को परास्त किया।\n3. तुलुव सम्राट कृष्णदेवराय ने तेलुगु में 'आमुक्तमाल्यद' लिखा जिसमें प्रशासन व कृषि व्यापार के सिद्धांत भी हैं।\n4. नूनिज ने अच्युतदेवराय के समय 3 वर्ष विजयनगर में रहकर महिलाओं के प्रशासनिक-सैन्य योगदान पर लिखा।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":0,"explanation":"कथन 1 असत्य है। सुधार: 'फ्रांस्वा बर्नियर एवं टैवर्नियर' का सही संबंध 'शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68)' से था — बर्नियर दारा शिकोह के चिकित्सक व दानिशमंद खाँ के संरक्षण में रहे तथा 12 वर्ष भारत भ्रमण किया।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. शाहजहाँ: स्थापत्य का स्वर्ण युग, तख्त-ए-ताऊस व उत्तराधिकार युद्ध   B. गुरु अर्जुन देव (पाँचवें गुरु)\nC. चोल स्थानीय स्वशासन एवं उत्तरमेरूर अभिलेख   D. किताब-उल-हिन्द\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["शाहजहाँ: स्थापत्य का स्वर्ण युग, तख्त-ए-ताऊस व उत्तराधिकार युद्ध","किताब-उल-हिन्द","गुरु अर्जुन देव (पाँचवें गुरु)","चोल स्थानीय स्वशासन एवं उत्तरमेरूर अभिलेख"],"correct":0,"explanation":"चोल स्थानीय स्वशासन एवं उत्तरमेरूर अभिलेख (919-921 ई.), किताब-उल-हिन्द (11वीं सदी ई.), गुरु अर्जुन देव (पाँचवें गुरु) (1604 ई.), शाहजहाँ: स्थापत्य का स्वर्ण युग, तख्त-ए-ताऊस व उत्तराधिकार युद्ध (1628-1658 ई.)। अतः सबसे अंत में शाहजहाँ: स्थापत्य का स्वर्ण युग, तख्त-ए-ताऊस व उत्तराधिकार युद्ध।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. शकरखेड़ा युद्ध (1724) के बाद निजाम-उल-मुल्क ने दक्कन में स्वतंत्र हैदराबाद राज्य की नींव रखी।\n2. अल-बरूनी ने 11वीं सदी में भारत की विद्या, धर्म, विज्ञान व समाज पर 'किताब-उल-हिन्द' लिखी।\n3. ऐतिहासिक युद्ध एवं परिणाम के अंतर्गत 'चौसा का युद्ध (1539 ई.)' का ऐतिहासिक संबंध 'अकबर-बैरम खाँ ने आदिल शाह के सेनापति हेमू (विक्रमादित्य) को हराया' से था।\n4. बरनी ने बलबन से फिरोजशाह तुगलक के प्रारंभिक काल तक का राजनीतिक इतिहास व राजत्व सिद्धांत लिखा।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: 'चौसा का युद्ध (1539 ई.)' का सही संबंध 'शेर खान (शेरशाह सूरी) ने हुमायूँ को पराजित कर 'शेरशाह' उपाधि धारण की' से था — 1539 ई. में बक्सर के निकट चौसा के युद्ध में शेरशाह सूरी ने हुमायूँ को पराजित किया।"}
]);
